  ui_story_5028_50280101_X95_dialog_content = "(เหอะ มั่นหน้าอะไรขนาดนั้น ทำไมฉันถึงยอมเป็นศิษย์หมอนั่นได้นะ?)",
  ui_story_5028_50280101_95_dialog_content = "ที่ฉันไม่เข้าใจก็คือ ทำไมนายถึงอยากให้ฉันพาไคโลไปด้วย?",
  ui_story_5028_50280101_96_dialog_content = "ฉัน... เราเป็นทีมที่ไม่เข้าขากันเลย มันเป็นคู่หูที่ไม่เหมาะกับฉันหรอก",
  ui_story_5028_50280101_97_dialog_content = "พอมีมันอยู่ ฉันก็ทำอะไรไม่ได้เลยสักอย่าง แบบนี้เมื่อไหร่ฉันจะได้เป็น<color=#FFB400>นักสัตว์มหัศจรรย์วิทยา</color>ล่ะ!",
  ui_story_5028_50280101_98_dialog_content = "เพราะเธอคุยกับมันไม่ได้ ใช่มั้ย?",
  ui_story_5028_50280101_99_dialog_content = "...",
  ui_story_5028_50280101_100_dialog_content = "ใช่",
  ui_story_5028_50280101_102_dialog_content = "ความสามารถของเธอในการสื่อสารกับสัตว์เป็นพรสวรรค์ที่ล้ำค่า แต่การพึ่งพามันมากเกินไปเป็นเรื่องที่ไม่ฉลาดเลย",
  ui_story_5028_50280101_103_dialog_content = "ยกตัวอย่างง่ายๆ เธอคุยกับออโรเรียนได้ แต่นั่นจะทำให้เธอเป็นเพื่อนกับออโรเรียนทุกคนได้รึเปล่า?",
  ui_story_5028_50280101_104_dialog_content = "โอ๊ะ โทษที ฉันลืมไปว่าเธอไม่มีเพื่อนอยู่แล้ว",
  ui_story_5028_50280101_105_dialog_content = "หนอย...!",
  ui_story_5028_50280101_106_dialog_content = "นายเองก็ไม่มีเหมือนกันนั่นแหละ! อย่าได้ใจไปหน่อยเลย",
  ui_story_5028_50280101_107_dialog_content = "มิตรภาพสำหรับผู้ใหญ่มันคนละแบบกันน่ะ เธอยังไม่เข้าใจหรอก",
  ui_story_5028_50280101_108_dialog_content = "ฮึ่ม ทำเป็นพูดดี ผู้ใหญ่อย่างนายก็ทำได้แค่หาเพื่อนคุยโม้ในบาร์เหล้า",
  ui_story_5028_50280101_109_dialog_content = "เอ่อ นั่นมัน...",
  ui_story_5028_50280101_110_dialog_content = "แถมยังต้องให้ลูกศิษย์ตัวเองมาใช้ค่าเหล้าแทนให้อีก!",
  ui_story_5028_50280101_111_dialog_content = "พวกวัยกลางคนขี้แพ้นี่เป็นอย่างนายทุกคนเลยหรือไง?",
  ui_story_5028_50280101_112_dialog_content = "ไม่มีเงิน ไม่ทำงาน เอาแต่นั่งขี้เกียจอยู่บ้านทั้งวัน!",
  ui_story_5028_50280101_113_dialog_content = "เอาล่ะ พอเถอะ แล้วเธอว่าใครเป็น \"พวกวัยกลางคนขี้แพ้\" กัน?",
  ui_story_5028_50280101_S113_dialog_content = "ก็คนที่ต้องฝากชีวิตไว้กับลูกศิษย์อย่างนายไงล่ะ!",
  ui_story_5028_50280101_S114_dialog_content = "ฉันต้องทำอาหารสามมื้อให้นายทุกวันก่อนออกไปข้างนอก พอกลับมาก็ต้องทำความสะอาดห้องที่เพื่อนตัวน้อยของนายทำรกอีก",
  ui_story_5028_50280101_S115_dialog_content = "หัดใช้ชีวิตด้วยตัวเองมั่งได้มั้ย? ทำตัวให้สมกับเป็นผู้ใหญ่หน่อย!",
  ui_story_5028_50280101_S116_dialog_content = "เธอ... เธอ...",
  ui_story_5028_50280101_114_dialog_content = "ฉันยังเป็นอาจารย์เธออยู่มั้ยเนี่ย? เธอควรจะพูดจาดี ๆ กับฉันหน่อยไม่ใช่หรือไง?",
  ui_story_5028_50280101_X114_dialog_content = "ก็ได้ งั้นฉันจะพูดดี ๆ...",
  ui_story_5028_50280101_X115_dialog_content = "(ไม่สิ เดี๋ยวก่อน! ฟีญ่า เธอคิดถูกแล้ว!)",
  ui_story_5028_50280101_X116_dialog_content = "(ถ้าแสดงจุดอ่อนให้หมอนั่นเห็น ทุกอย่างก็จะกลับเป็นเหมือนเดิมอีก)",
