  ui_story_5028_50280201_10_dialog_content = "<color=#e8d9bb>ซวบ... ซวบ...</color>",
  ui_story_5028_50280201_11_dialog_content = "โอเค ต่อไปฉันจะขว้างบอลไปหาเธอ แล้วเธอก็ใช้ไม้ที่ถืออยู่ฟาดบอลให้โดน",
  ui_story_5028_50280201_12_dialog_content = "รูบี้ศึกษาวัฒนธรรมโบราณมาเยอะ แล้วเธอก็อธิบายกติกาเกมนี้ให้ฉันฟังแล้ว!",
  ui_story_5028_50280201_13_dialog_content = "อธิบายง่าย ๆ ก็คือ ยิ่งตีบอลไปไกลเท่าไหร่ก็ยิ่งดีเท่านั้น",
  ui_story_5028_50280201_14_dialog_content = "เข้าใจนะ?",
  ui_story_5028_50280201_15_dialog_content = "เข้าใจแล้ว! ฟาดลูกบอลด้วยไม้",
  ui_story_5028_50280201_16_dialog_content = "โอเค! มาลองกันเลย",
  ui_story_5028_50280201_17_dialog_content = "3, 2, 1!",
  ui_story_5028_50280201_18_dialog_content = "ตีเลย!",
  ui_story_5028_50280201_19_dialog_content = "<color=#e8d9bb>ฟึ่บ!</color>",
  ui_story_5028_50280201_20_dialog_content = "อ้าว หลบทำไมล่ะ?",
  ui_story_5028_50280201_21_dialog_content = "PlayerName นายโจมตีฉันทำไมน่ะ?",
  ui_story_5028_50280201_22_dialog_content = "ไม่ได้โจมตี เขาเรียกว่า \"ขว้างลูก\" เฉย ๆ",
  ui_story_5028_50280201_23_dialog_content = "ขว้างลูก?",
  ui_story_5028_50280201_24_dialog_content = "ใช่ ฉันขว้างบอลไปทางเธอ แล้วเธอก็ตีลูกกลางอากาศด้วยไม้ นี่ล่ะกติกาของเกม",
  ui_story_5028_50280201_25_dialog_content = "โอเค เข้าใจแล้ว งั้นเอาใหม่",
  ui_story_5028_50280201_26_dialog_content = "เยี่ยม ถ้าตีไม่โดนก็ไม่ต้องกังวลนะ หัดแรก ๆ ก็แบบนี้แหละ",
  ui_story_5028_50280201_27_dialog_content = "ได้",
  ui_story_5028_50280201_28_dialog_content = "เตรียมตัวนะ! 3, 2, 1—",
  ui_story_5028_50280201_29_dialog_content = "ตีเลย!",
  ui_story_5028_50280201_30_dialog_content = "<color=#e8d9bb>ฟิ้วววว!</color>",
  ui_story_5028_50280201_31_dialog_content = "<color=#e8d9bb>ผัวะ!!!</color>",
  ui_story_5028_50280201_32_dialog_content = "ว้าว! ตีโดนด้วย",
  ui_story_5028_50280201_33_dialog_content = "โอ้! ฉันทำได้!",
  ui_story_5028_50280201_34_dialog_content = "บอลลอยไปไกลมากเลย!",
  ui_story_5028_50280201_35_dialog_content = "ตำนานโบราณเรียกมันว่า \"โฮมรัน\"",
  ui_story_5028_50280201_36_dialog_content = "เฮ้ เรวี่ เธออาจจะมีพรสวรรค์ในการตีเบสบอลก็ได้นะ?",
  ui_story_5028_50280201_37_dialog_content = "ฉัน? มีพรสวรรค์งั้นเหรอ?",
  ui_story_5028_50280201_38_dialog_content = "ใช่! สำหรับการตีลูกครั้งแรก นี่มันเยี่ยมมากเลยนะ!",
  ui_story_5028_50280201_39_dialog_content = "ตีเบสบอลสนุกจัง",
  ui_story_5028_50280201_40_dialog_content = "แล้วต้องทำไงต่อเหรอ?",
  ui_story_5028_50280201_41_dialog_content = "ต่อไปก็...",
