  ui_story_5028_50280201_43_dialog_content = "ว้าว ลอยไปไกลขนาดนั้นก็ลำบากเหมือนกันแฮะ...",
  ui_story_5028_50280201_44_dialog_content = "ขอโทษนะ ครั้งหน้าเดี๋ยวตีเบา ๆ ให้ก็ได้",
  ui_story_5028_50280201_45_dialog_content = "โอ๊ะ ไม่ต้องทำแบบนั้นหรอก กติกาบอกว่าต้องตีไปให้ไกลที่สุดน่ะนะ",
  ui_story_5028_50280201_46_dialog_content = "งั้น... ฉันไปเก็บบอลเอง ฉันวิ่งเร็วกว่า",
  ui_story_5028_50280201_47_dialog_content = "นี่มันเกิน 5 นาทีแล้วนะ ทำไมเรวี่ยังไม่กลับมาอีกเนี่ย?",
  ui_story_5028_50280201_48_dialog_content = "<color=#e8d9bb>ซวบ...</color>",
  ui_story_5028_50280201_49_dialog_content = "เธอหาบอลไม่เจองั้นเหรอ? หรือว่าเกิดเรื่องอะไรกับเธอรึเปล่า?",
  ui_story_5028_50280201_50_dialog_content = "เห็นไวซ์บอกว่ามีอิคลิพไซท์อยู่แถวนี้ด้วยนี่",
  ui_story_5028_50280201_51_dialog_content = "<color=#e8d9bb>ซวบ... ซวบ...</color>",
  ui_story_5028_50280201_52_dialog_content = "แต่ถ้าเป็นอิคลิพไซท์ธรรมดา เรวี่ก็น่าจะจัดการได้สบาย ๆ อยู่แล้ว",
  ui_story_5028_50280201_53_dialog_content = "ยังไงซะ เธอก็เป็นถึงเรวี่...",
  ui_story_5028_50280201_54_dialog_content = "จังหวะนี้แหละ!",
  ui_story_5028_50280201_55_dialog_content = "!? ตาข่ายอะไรเนี่ย?",
  ui_story_5028_50280201_56_dialog_content = "ไคโล เจ้าบื้อ! พลาดอีกแล้วนะ",
  ui_story_5028_50280201_57_dialog_content = "เอาล่ะ ถ้างั้นก็ไม่มีทางเลือก โจมตี!",
  ui_story_5028_50280201_58_dialog_content = "นี่ เธอเป็นใคร? ขอเตือนไว้ก่อน ฉันน่ะแข็งแกร่งมากนะ",
  ui_story_5028_50280201_59_dialog_content = "ส่วนออโรเรียนที่มากับฉัน เธอแค่ใช้มือเปล่าก็ผ่าอิคลิพไซท์เป็นสองซีกได้เหมือนผ่าแตงโม!",
  ui_story_5028_50280201_60_dialog_content = "ถ้าเข้ามาใกล้ล่ะก็ ฉันจะใช้พลังจิตขอความช่วยเหลือนะ",
  ui_story_5028_50280201_61_dialog_content = "\"พลังจิต\"? นายเป็นเคเลสไทต์สินะ!",
  ui_story_5028_50280201_62_dialog_content = "เราต้องหยุดไม่ให้หมอนั่นขอความช่วยเหลือ!",
  ui_story_5028_50280201_63_dialog_content = "ไคโล ใช้แผน B! เร็วเข้า!",
  ui_story_5028_50280201_64_dialog_content = "โล!",
  ui_story_5028_50280201_65_dialog_content = "เดี๋ยว! แผน B อะไรน่ะ?",
  ui_story_5028_50280201_66_dialog_content = "ฉันเอาจริงนะ ถ้าเข้ามาอีกก้าวเดียวฉันร้องให้คนช่วยจริง ๆ ด้วย",
  ui_story_5028_50280201_67_dialog_content = "ไป—",
  ui_story_5028_50280201_68_option_content = "บังคับเชื่อมกระแส—โอ๊ย!",
  ui_story_5028_50280201_69_dialog_content = "เจ็บนะ!",
  ui_story_5028_50280201_70_dialog_content = "โล โล โล!",
  ui_story_5028_50280201_71_dialog_content = "ดีมาก ไคโล เอาล่ะ หนีทางป่าตามแผน!",
  ui_story_5028_50280201_72_dialog_content = "โล โล!",
  ui_story_5028_50280201_73_dialog_content = "วางฉันลงนะ! เธอจะพาฉันไปไหน!",
  ui_story_5028_50280201_74_dialog_content = "<anim type=Shake><size=45>เรวี่—เรวี่—!</size></anim>",
  ui_story_5028_50280201_76_dialog_content = "ฉันกลับมาแล้ว นึกว่ากระต่ายเป็นลูกบอลน่ะ ไล่ตามซะนานเลย",
  ui_story_5028_50280201_77_dialog_content = "เอ๊ะ? PlayerName ไปไหนแล้วล่ะ?",
  ui_story_5028_50280201_78_dialog_content = "ไม้ยังอยู่ตรงนี้เลย อ๋อ! PlayerName อยากให้ฉันฝึกตีโฮมรันสินะ",
  ui_story_5028_50280201_79_dialog_content = "ฉันจะไม่ทำให้นายผิดหวัง! ขั้นแรก ฝึกหวดไม้ 1,000 ครั้ง เตรียมตัว... เริ่ม!",
  ui_story_5028_50280201_80_dialog_content = "โล!",
  ui_story_5028_50280201_81_dialog_content = "เดี๋ยวสิ เดี๋ยว เจ้าตัวประหลาดนี่จะพาฉันไปไหนน่ะ?",
  ui_story_5028_50280201_82_dialog_content = "วางฉันลงก่อน ฉันเจ็บจะตายอยู่แล้วเนี่ย หลังหักรึเปล่าก็ไม่รู้",
  ui_story_5028_50280201_83_dialog_content = "โล?",
  ui_story_5028_50280201_84_dialog_content = "ไคโล หยุดก่อน!",
  ui_story_5028_50280201_85_dialog_content = "ฟู่... ในที่สุดก็ยอมฟังซักที โอ๊ย โอ๊ย โอ๊ย",
  ui_story_5028_50280201_86_dialog_content = "ไคโล นี่มันใช่เส้นทางตามแผน B จริง ๆ เหรอ?",
  ui_story_5028_50280201_87_dialog_content = "โล โล?",
  ui_story_5028_50280201_88_dialog_content = "อย่าบอกนะว่าแกวิ่งเข้าป่ามามั่ว ๆ น่ะ...",
  ui_story_5028_50280201_89_dialog_content = "โล...",
  ui_story_5028_50280201_90_dialog_content = "รอบ ๆ นี่ไม่เหมือนเส้นทางที่เรามาเลย... มัน... มองไปทางไหนก็มีแต่ต้นไม้แฮะ",
  ui_story_5028_50280201_91_dialog_content = "พวกเธอเสียสติหรือไง ไม่รู้เหรอว่าในป่ามันมีอิคลิพไซท์เต็มไปหมดน่ะ?",
