  ui_story_5028_50280201_94_dialog_content = "มาจริง ๆ ด้วย!",
  ui_story_5028_50280201_95_dialog_content = "หา!? มีอิคลิพไซท์ได้ยังไงน่ะ!",
  ui_story_5028_50280201_96_dialog_content = "อย่ามัวยืนอึ้งสิ! วิ่งเร็ว!",
