  ui_story_5028_50280201_98_dialog_content = "ไคโล!",
  ui_story_5028_50280201_99_dialog_content = "โล!",
  ui_story_5028_50280201_100_dialog_content = "อิคลิพไซท์? ที่นี่มีอิคลิพไซท์ได้ยังไงกัน?",
  ui_story_5028_50280201_101_dialog_content = "เลิกคิดแล้ววิ่งได้แล้ว!",
