  ui_story_5028_50280201_103_dialog_content = "ถึงฉันจะเก่งเรื่องพูดคุยกับสัตว์มหัศจรรย์ แต่ให้คุยกับอิคลิพไซท์เนี่ยนะ? อี๋!",
  ui_story_5028_50280201_104_dialog_content = "แต่ฉันจะมาโดนอิคลิพไซท์กินไม่ได้ ฉันต้องเป็นนักสัตว์มหัศจรรย์วิทยาให้ได้ก่อน!",
