  ui_story_5028_50280201_107_dialog_content = "หรือฉันควรถ่วงเวลาให้ไคโลกับเคเลสไทต์หนีไป",
  ui_story_5028_50280201_108_dialog_content = "แต่ฉันไม่รู้ว่าตัวเองแข็งแกร่งพอรึเปล่า... ต้องทำให้ได้สิ! พวกเขาตายจะมาตายเพราะฉันไม่ได้",
  ui_story_5028_50280201_109_dialog_content = "เอ่อ ใจเย็นก่อนนะ เธอต่อสู้เป็นรึเปล่า?",
  ui_story_5028_50280201_110_dialog_content = "ฮือ... ก็นิดหน่อย ส่วนใหญ่ก็ได้แค่ป้องกันตัวน่ะ",
  ui_story_5028_50280201_111_dialog_content = "ไม่มีปัญหา ศัตรูตอนเราเริ่มผจญภัยมันจะไม่ค่อยเก่งอยู่แล้ว",
  ui_story_5028_50280201_112_dialog_content = "ใช่แล้ว ชะตากรรมมันมามุกนี้ตลอดนั่นแหละ",
  ui_story_5028_50280201_113_dialog_content = "ฉันใช้พลังจิตช่วยเธอได้นะ",
  ui_story_5028_50280201_114_dialog_content = "ถ้าหนีไปทั่วป่าก็มีแต่จะปลุกอิคลิพไซท์ขึ้นมามากกว่าเดิม",
  ui_story_5028_50280201_114X_dialog_content = "เราต้องจัดการพวกที่ไล่ตามเรามาก่อน เดี๋ยวค่อยคิดว่าจะเอาไงต่อ",
  ui_story_5028_50280201_115_dialog_content = "แต่พวกมันเยอะมากเลย...",
  ui_story_5028_50280201_116_dialog_content = "เชื่อฉันเถอะน่า!",
  ui_story_5028_50280201_117_dialog_content = "เราไม่ได้มีกันแค่สองคนซักหน่อย เพื่อนของเธอก็อยู่ด้วยนี่ ถ้าร่วมมือกันเราจัดการพวกมันได้แน่",
  ui_story_5028_50280201_118_dialog_content = "โล!",
  ui_story_5028_50280201_119_dialog_content = "ฮือ... ก็ได้!",
  ui_story_5028_50280201_120_dialog_content = "เลิกเรียกฉันว่า \"เธอ\" ได้แล้ว! ฉันเป็นถึงผู้เชี่ยวชาญด้านสัตว์มหัศจรรย์วิทยาอันดับหนึ่งของโลกเลยนะ! มีมารยาทหน่อย!",
  ui_story_5028_50280201_121_dialog_content = "พวกอิคลิพไซท์น่ารังเกียจ กล้าดียังไงถึงมาทำให้ฉันตกใจ?",
  ui_story_5028_50280201_122_dialog_content = "เข้าแถวให้ดีล่ะ ฉันจะจัดการแกเรียงตัวเลย!",
  ui_story_5028_50280202_1_dialog_content = "ว้าว เราชนะจริง ๆ ด้วย",
  ui_story_5028_50280202_2_dialog_content = "ยอดเลย ไคโล แกเห็นมั้ย?",
  ui_story_5028_50280202_3_dialog_content = "โล! โล!",
  ui_story_5028_50280202_4_dialog_content = "ฮิฮิ~ ไม่นึกเลยว่าแกจะแข็งแกร่งพอตัวนะเนี่ย~ ฟีญ่าต้องมองแกใหม่แล้วสิ",
  ui_story_5028_50280202_5_dialog_content = "โล!",
  ui_story_5028_50280202_6_dialog_content = "(ระหว่างที่พวกนั้นกำลังดีใจ ฉันน่าจะใช้โอกาสนี้หนีไป)",
  ui_story_5028_50280202_7_dialog_content = "เอ่อ...",
  ui_story_5028_50280202_8_dialog_content = "(แต่ข้างนอกยังมีอิคลิพไซท์ หนีไปตอนนี้ก็ไม่ปลอดภัยอยู่ดี)",
  ui_story_5028_50280202_9_dialog_content = "(เฮ้อ...)",
  ui_story_5028_50280202_10_dialog_content = "เอ่อ คุณเคเลสไทต์?",
  ui_story_5028_50280202_11_dialog_content = "อ๊ะ ว่าไง",
  ui_story_5028_50280202_12_dialog_content = "ขอบคุณ... ที่ช่วยฟีญ่ากับไคโลนะ",
  ui_story_5028_50280202_13_dialog_content = "อ๋อ ไม่มีปัญหา เรื่องเล็กน้อยน่ะ",
  ui_story_5028_50280202_14_dialog_content = "ไม่จำเป็นต้องขอบคุณฉันหรอก เอาเป็นว่าฉันกลับก่อนดีกว่า จะได้ไม่ถ่วงพวกเธอ",
  ui_story_5028_50280202_15_dialog_content = "ไม่ได้หรอกนะ คุณเคเลสไทต์",
  ui_story_5028_50280202_16_dialog_content = "หลังจากที่เห็นฉันในสภาพดูไม่จืดแบบนั้น",
  ui_story_5028_50280202_17_dialog_content = "ม-เมื่อกี้เกิดอะไรขึ้นเหรอ? ที่นี่ที่ไหนน่ะ? ฉันจำอะไรไม่ได้เลย",
  ui_story_5028_50280202_18_dialog_content = "แกล้งทำเป็นความจำเสื่อมไปมันก็ไม่ช่วยหรอกนะ",
  ui_story_5028_50280202_19_dialog_content = "ทำตัวเป็นเด็กดี มาเป็นคู่หูและสัตว์เลี้ยงของฉันแบบไคโล แล้วก็อยู่ช่วยงานฉันซะ",
  ui_story_5028_50280202_20_dialog_content = "(ฮิฮิ ใช้รอยยิ้มกระชากใจของฟีญ่าจัดการเคเลสไทต์ในกระบวนท่าเดียวดีกว่า!)",
  ui_story_5028_50280202_21_dialog_content = "ไม่มีทาง! ฉันขอปฏิเสธ!",
  ui_story_5028_50280202_22_dialog_content = "หา?!",
  ui_story_5028_50280202_23_dialog_content = "ที่ฉันช่วยเมื่อกี้ก็เพราะมันเป็นสิ่งที่ควรทำ ไม่ได้หมายความว่าฉันเชื่อฟังเธอซะหน่อย",
  ui_story_5028_50280202_24_dialog_content = "แล้วเราก็ยังไม่ได้เคลียร์กันเลย เรื่องที่เจ้าไคโลนี่ซัดฉันหมอบแล้วก็ลักพาตัวฉันมา",
  ui_story_5028_50280202_25_dialog_content = "มาช่วยกันเอาตัวรอดออกไปจากป่าให้ได้ก่อนเถอะ แล้วค่อยแยกกันไปคนทาง",
  ui_story_5028_50280202_26_dialog_content = "ฮึก...",
  ui_story_5028_50280202_27_dialog_content = "(พูดแรงไปรึเปล่านะ?)",
  ui_story_5028_50280202_28_dialog_content = "(ไม่สิ ไม่หรอก เด็กผู้หญิงคนนี้อาจจะพยายามหลอกฉัน แล้วฉันก็ไม่เชื่อใจเจ้าไคโลนั่นเหมือนกัน)",
  ui_story_5028_50280202_29_dialog_content = "โฮวว...",
  ui_story_5028_50280202_30_dialog_content = "แต่ฉันแค่... คือ ฉันแค่อยากมีเพื่อนเท่านั้นเอง",
  ui_story_5028_50280202_31_dialog_content = "โล...",
  ui_story_5028_50280202_32_dialog_content = "ใคร ๆ ก็บอกว่ามีแต่สัตว์มหัศจรรย์ที่ชอบฟีญ่า แต่ฟีญ่าอยากจะพิสูจน์ตัวเอง ว่าฉันก็ผูกมิตรกับออโรเรียนและเคเลสไทต์ได้เหมือนกัน...",
  ui_story_5028_50280202_33_dialog_content = "ถ้าทำสำเร็จ ความปรารถนาสุดท้ายของอาจารย์ก็จะเป็นจริง...",
  ui_story_5028_50280202_34_dialog_content = "(อาจารย์? คนที่เธอเรียกว่าเจ้าโง่น่ะนะ? ว่าแต่ความปรารถนาสุดท้ายนี่หมายความว่าไงน่ะ? เขาตายแล้วงั้นเหรอ?)",
  ui_story_5028_50280202_35_dialog_content = "ฮัดเช่ย!",
  ui_story_5028_50280202_36_dialog_content = "ฉันไม่เป็นไร เจ้าตัวน้อย สงสัยจะเป็นหวัดล่ะมั้ง",
  ui_story_5028_50280202_37_dialog_content = "เป็นห่วงฉันเหรอ? งั้นขอใช้แกเช็ดจมูกได้มั้ย?",
  ui_story_5028_50280202_38_dialog_content = "ฮ่าฮ่า แน่นอน ฉันพูดเล่นน่ะ ถ้าแกเปื้อนน้ำมูกฉันก็เอาขนของแกไปแลกเหล้าไม่ได้น่ะสิ",
  ui_story_5028_50280202_39_dialog_content = "(คงไม่ปล่อยโฮออกมาจริง ๆ ใช่มั้ยเนี่ย? ตาเธอแดงหมดแล้ว)",
  ui_story_5028_50280202_40_dialog_content = "(เธอดูอายุน้อยกว่าเรวี่อีก แล้วก็สู้ไม่เก่งซะด้วย)",
  ui_story_5028_50280202_40X_dialog_content = "(การใช้ชีวิตในโลกภายนอกคงจะลำบากน่าดู)",
  ui_story_5028_50280202_41_dialog_content = "เพราะแบบนั้น ฟีญ่าก็เลยลักพาตัวคุณเคเลสไทต์มา เราจะได้เป็นเพื่อนกัน",
  ui_story_5028_50280202_42_dialog_content = "(อย่าร้องนะ อย่าร้องนะ อย่าเด็ดขาดเลย)",
  ui_story_5028_50280202_43_dialog_content = "ฉันขอโทษ ขอโทษจริง ๆ ฟีญ่าสำนึกผิดแล้วที่ทำตัวไม่ดี",
  ui_story_5028_50280202_44_dialog_content = "แต่ถ้าคุณเคเลสไทต์เกลียดฟีญ่าแล้ว จะทิ้งฟีญ่าไว้คนเดียวก็ได้...",
