  ui_story_5028_50280202_47_dialog_content = "ก็ได้ ก็ได้ ฉันผิดไปแล้ว!",
  ui_story_5028_50280202_48_dialog_content = "ขอโทษนะ ฉันไม่น่าใจร้ายกับเธอเลย",
  ui_story_5028_50280202_49_dialog_content = "เธออยากมีเพื่อนใช่มั้ย ฉันยินดีเป็นเพื่อนกับเธอนะ ฉันชื่อ PlayerName",
  ui_story_5028_50280202_50_dialog_content = "จ-จริงเหรอ? ฉันชื่อฟีญ่า",
  ui_story_5028_50280202_51_dialog_content = "โอเค ฟีญ่า งั้นเรามาเป็นเพื่อนกันนะ",
