  ui_story_5028_50280202_54_dialog_content = "โล!",
  ui_story_5028_50280202_55_dialog_content = "ฮิฮิ... นี่ PlayerName นายเป็นเพื่อนคนแรกของฉันเลยนะ!",
  ui_story_5028_50280202_56_dialog_content = "นายเต็มใจเป็นเพื่อนกับฟีญ่า ฟีญ่าดีใจที่สุดเลย!",
