  ui_story_5028_50280202_59_dialog_content = "(บ้าเอ๊ย! ทำให้ใจอ่อนด้วยน้ำตา แล้วจู่ ๆ ก็เปลี่ยนมาใช้รอยยิ้มน่ารักงั้นเรอะ?)",
  ui_story_5028_50280202_60_dialog_content = "(เธอใช้ชีวิตโดยไม่มีเพื่อน เหมือนกับฉันเมื่อก่อนงั้นเหรอ? ไม่สิ อย่างน้อยฉันก็มีโซรอซ)",
  ui_story_5028_50280202_61_dialog_content = "(แต่เธอก็มีเจ้าตัวที่ชื่อไคโลล่ะนะ)",
  ui_story_5028_50280202_62_dialog_content = "(ถึงเมื่อกี้จะเป็นแค่การเล่นละคร แต่ฉันก็คงปล่อยเด็กผู้หญิงนั่งร้องไห้คนเดียวกลางภูเขาไม่ได้อยู่ดี)",
  ui_story_5028_50280202_63_dialog_content = "นี่ PlayerName คิดอะไรอยู่เหรอ PlayerName?",
  ui_story_5028_50280202_64_dialog_content = "โอ๊ะ ไม่มีอะไร แค่คิดว่าเราควรกลับกันได้แล้ว ฉันจะได้ขับโคลอสซัสพาเธอไปส่งที่บ้าน",
  ui_story_5028_50280202_65_dialog_content = "จริงด้วย! ลืมไปเลยว่าเคเลสไทต์มีโคลอสซัสนะเนี่ย",
  ui_story_5028_50280202_66_dialog_content = "เยี่ยม ถ้าใช้โคลอสซัสเดินทาง แบบนี้การทดลองของอาจารย์จะต้องเสร็จอย่างไวแน่ ๆ!",
  ui_story_5028_50280202_67_dialog_content = "ไปกันเถอะ ไปกันเถอะ พี่ PlayerName~",
  ui_story_5028_50280202_68_dialog_content = "เอ๋? การทดลองอะไรน่ะ? ปล่อยมือฉันนะ",
  ui_story_5028_50280202_69_dialog_content = "โอ๊ย! หยุดลากได้แล้ว ฉันยังเจ็บหลังไม่หายเลยนะ!",
