  ui_story_5028_50280202_73_dialog_content = "ทำไม PlayerName ยังไม่กลับมาอีก? ฉันซ้อมเสร็จแล้วนะ",
  ui_story_5028_50280202_74_dialog_content = "หรือว่ากลับไปที่โคลอสซัสแล้ว? ไปดูหน่อยดีกว่า",
  ui_story_5028_50280202_75_dialog_content = "เอ๊ะ?",
  ui_story_5028_50280202_76_dialog_content = "โคลอสซัสอยู่ไหนแล้วล่ะ?",
  ui_story_5028_50280202_77_dialog_content = "PlayerName ก็หายไปด้วย",
  ui_story_5028_50280202_78_dialog_content = "หา?",
