  ui_story_5028_50280301_16_dialog_content = "ก่อนทำงานกับสัตว์มหัศจรรย์ เราจำเป็นต้องทบทวนข้อมูลเกี่ยวกับคุณลักษณะของมัน",
  ui_story_5028_50280301_17_dialog_content = "ยิ่งกับสัตว์มหัศจรรย์หายากอย่างเดรโก้ไลออน เรายิ่งต้องศึกษาเรื่องที่อยู่อาศัยของพวกมันอย่างละเอียด",
  ui_story_5028_50280301_18_dialog_content = "และการอ่านออกเสียงก็ทำให้เรารู้สึกเหมือนได้ทำพิธีบางอย่าง ช่วยให้สงบใจเวลาเกิดเหตุฉุกเฉิน",
  ui_story_5028_50280301_19_dialog_content = "โล โล!",
  ui_story_5028_50280301_20_dialog_content = "... เริ่มหวั่น ๆ แล้วสิ เธอไม่เคยเจอมันมาก่อนใช่มั้ย เลยต้องมาอ่านทบทวนแบบนี้?",
  ui_story_5028_50280301_21_dialog_content = "อะแฮ่ม ไม่ต้องห่วง ฟีญ่าศึกษามาอย่างดีแล้ว คราวนี้เรามีโอกาสเจอเดรโก้ไลออน 99%",
