  ui_story_5028_50280301_27_dialog_content = "อะไรนะ? \"ตก\" แล้ว \"ทอด\" ด้วยเหรอ? ไม่เห็นจะเข้าใจเลย? เอาเถอะ ช่วยเงียบก่อนนะ ฉันอ่านถึงส่วนสำคัญแล้ว",
