  ui_story_5028_50280301_30_dialog_content = "เมื่อมีภัยคุกคาม เดรโก้ไลออนก็จะเรียกสายฟ้าและใช้กรงเล็บฉีกกระชากศัตรูที่โง่พอจะต่อกรกับมัน",
  ui_story_5028_50280301_31_dialog_content = "แต่เมื่อมันออกไข่เสร็จแล้ว มันก็จะไม่สนใจเลยว่าไข่ใบนั้นจะหล่นลงพื้นอย่างปลอดภัยและฟักตัวได้หรือไม่",
  ui_story_5028_50280301_32_dialog_content = "บางที การบังคับให้ลูกเดรโก้ไลออนตัวน้อยเผชิญโลกอันโหดร้ายตามลำพัง อาจเป็นการคัดเลือกเพื่อให้แน่ใจว่ามีเพียงเดรโก้ไลออนที่แข็งแกร่งที่สุดเท่านั้น ที่จะเติบโตไปเป็นราชาแห่งท้องฟ้า",
