  ui_story_5028_50280401_6_dialog_content = "โล",
  ui_story_5028_50280401_7_dialog_content = "ชู่วว ฟีญ่ากำลังจัดบันทึกการเติบโตของลูกเดรโก้ไลออนอยู่",
  ui_story_5028_50280401_8_dialog_content = "ไม่อยากเชื่อเลยว่ามันจะโตเร็วขนาดนี้ ตอนนี้มันตัวโตกว่าไคโลแล้ว แถมยังดูแลตัวเองได้ทั้ง ๆ ที่เพิ่งเกิดมาไม่นาน",
