  ui_story_5028_50280401_16_dialog_content = "ถอยไป!",
  ui_story_5028_50280401_17_dialog_content = "ไคโล ช่วยฉันจับ PlayerName หน่อยสิ",
  ui_story_5028_50280401_18_dialog_content = "โล โล!",
  ui_story_5028_50280401_19_dialog_content = "อุ๊! อึ๊ก อึ๊ก อึ๊ก!",
  ui_story_5028_50280401_20_dialog_content = "เผ็ดชะมัด! ไม่สิ เดี๋ยวนะ ทำไมมีกลิ่นนมล่ะ? เอ๊ะ รสมันเปลี่ยนไปอีกแล้ว... เย็นจัง?",
