  ui_story_5028_50280401_26_dialog_content = "โล~",
  ui_story_5028_50280401_27_dialog_content = "แหยะ ไคโล ทำไมแกถึงช่วยเธอทำของแบบนี้ล่ะเนี่ย?",
  ui_story_5028_50280401_28_dialog_content = "โล?",
