  ui_story_5028_50280401_30_dialog_content = "หืม?",
  ui_story_5028_50280401_31_dialog_content = "เธอจะมาผลิตยาเองแล้วบังคับให้คนอื่นเป็นหนูลองยาไม่ได้นะ! นี่มันผิดกฎหมาย ผิดร้ายแรงเลยด้วย!",
