  ui_story_5028_50280401_37_dialog_content = "ฉันรู้สึกดีขึ้นมาก สดชื่น แล้วก็มีเรี่ยวแรงขึ้นมา",
  ui_story_5028_50280401_38_dialog_content = "เห็นมั้ย มันได้ผล! รอแป๊บนะ ขอจดสูตรก่อน",
  ui_story_5028_50280401_39_dialog_content = "เดี๋ยวนะ นี่เธอใช้เป็นครั้งแรกเรอะ? กับฉันที่เป็นเคเลสไทต์คนเดียวที่เหลืออยู่เนี่ยนะ?",
