  ui_story_5028_50280401_64_dialog_content = "เข่าของฉันบาดเจ็บระหว่างสู้กับอิคลิพไซท์ ศึกครั้งนั้นฉันต่อสู้เคียงข้างลอร์ดชวาตส์ด้วยนะ",
