  ui_story_5028_50280401_67_dialog_content = "แต่สุดท้ายก็โดนผู้บังคับบัญชาจับได้ เลยถูกปลดประจำการก่อนกำหนด แล้วก็โดนส่งมาปลูกองุ่นแบบนี้",
