  ui_story_5028_50280402_36_dialog_content = "ฟู่...",
  ui_story_5028_50280402_37_dialog_content = "<size=45>ฉันขอโทษ ฉันขอโทษ ฉันขอโทษ! ฟีญ่าสำนึกผิดแล้ว!</size>",
