  ui_story_5028_50280602_21_dialog_content = "มันยินดีช่วย แล้วก็อยากจะเดินทางไปกับเรา!",
  ui_story_5028_50280602_22_dialog_content = "เปโกะ~",
  ui_story_5028_50280602_22X1_dialog_content = "เรียบร้อย! เรากลับไปหาอาจารย์ได้แล้ว!",
  ui_story_5028_50280602_23_dialog_content = "เอาเถอะ เท่านี้ก็เหมือนมีทั้งสวนสัตว์คอยติดตามเราอยู่แล้ว จะเพิ่มมาอีกซักตัวก็คงไม่เสียหาย",
  ui_story_5028_50280602_24_dialog_content = "ฮิฮิ... นายนี่ใจดีจัง PlayerName",
  ui_story_5028_50280602_25_dialog_content = "หา? แกคือกระต่ายเปโกะโชคดีที่เคยถูกช่วยจากเงื้อมมือของสัตว์ประหลาดน่ากลัวงั้นเหรอ?",
  ui_story_5028_50280602_26_dialog_content = "วิเศษไปเลย! ฉันมั่นใจว่าแกจะเป็นเครื่องรางนำโชคให้กับการเดินทางของเรา ฝากด้วยนะ~",
  ui_story_5028_50280602_27_dialog_content = "เปโกะ~",
  ui_story_5028_50280602_28_dialog_content = "เรวี่! โจมตี!",
  ui_story_5028_50280602_29_dialog_content = "<color=#e8d9bb>ปัง! ปัง!</color>",
  ui_story_5028_50280602_30_dialog_content = "จงไหม้ไปซะ! แมนติคอร์!",
  ui_story_5028_50280602_31_dialog_content = "น-หนีกันเถอะ! ยัยพวกนี้มันโหดจริง ๆ!",
  ui_story_5028_50280602_32_dialog_content = "ฟังให้ดี! พ-พวกเรา<color=#FFB400>แก๊งแส้เหล็ก</color> และบอสของเรา <color=#FFB400>แกรี่</color> จะไม่ลืมแกแน่นอน ฝากไว้ก่อนเถอะ!",
  ui_story_5028_50280602_33_dialog_content = "พวกมันไปซะแล้ว",
  ui_story_5028_50280602_34_dialog_content = "อุตส่าห์ออกมาตามหาเคเลสไทต์ แต่กลับเจอนักล่าป่าเถื่อน...",
  ui_story_5028_50280602_35_dialog_content = "พวกมันมาตามหาอะไรกันแน่นะ? อยากรู้จังว่านี่จะเกี่ยวกับปัญหาของ PlayerName รึเปล่า?",
  ui_story_5028_50280602_36_dialog_content = "ชิ... รู้งี้ถ้ามีโอกาส ฉันจับมันมาสอบปากคำซะก็ดี",
  ui_story_5028_50280602_37_dialog_content = "ยู้ฮู! พวกคุณเป็นเพื่อนซี้ของ PlayerName นี่นา?",
  ui_story_5028_50280602_38_dialog_content = "โลล่า? เธอมาทำอะไรที่นี่น่ะ?",
  ui_story_5028_50280602_39_dialog_content = "ฉันได้ยินเสียงปืนตอนกำลังส่งจดหมาย ก็เลยมาตรวจดูน่ะ พวกคุณบาดเจ็บอะไรมั้ย?",
  ui_story_5028_50280602_40_dialog_content = "เรากำลังตามหาเคเลสไทต์ แล้วกลุ่มนักล่าก็โจมตีเราทันทีที่เห็น",
  ui_story_5028_50280602_41_dialog_content = "ไม่มีใครบาดเจ็บ แล้วพวกนักล่าก็หนีไปนานแล้ว",
  ui_story_5028_50280602_42_dialog_content = "หืม? \"เคเลสไทต์\"? หมายความว่า PlayerName หายตัวไปงั้นเหรอ?",
  ui_story_5028_50280602_43_dialog_content = "เดี๋ยวก่อนนะ พอพูดแบบนั้นแล้ว... ฉันเจอร่องรอยคนมาตั้งแคมป์ชั่วคราวตรงโน้นด้วย! ลองไปสืบหาเบาะแสดูมั้ย?",
  ui_story_5028_50280602_44_dialog_content = "ตามฉันมาเลย! เดี๋ยวฉันไปส่งจดหมายทีหลังก็ได้",
  ui_story_5028_50280602_45_dialog_content = "ทำไมอยู่ ๆ เราก็กลายเป็นกรุ๊ปทัวร์ได้ล่ะเนี่ย?",
  ui_story_5028_50280602_46_dialog_content = "แบบนี้มันก็สนุกดีไม่ใช่หรือไง? ดูวิวสวย ๆ ตามที่ต่าง ๆ แล้วก็ไล่เตะพวกศัตรูไปด้วย...",
  ui_story_5028_50280602_47_dialog_content = "อืมม ก็เป็นวันหยุดที่เยี่ยมไปเลยแฮะ...",
  ui_story_5028_50280701_1_dialog_content = "บททดสอบ: ต้านทานการเย้ายวนอันแสนหวาน",
  ui_story_5028_50280701_2_dialog_content = "ก้อนเมฆขาวโพลน ก้านไม้เขียวขจี♪",
  ui_story_5028_50280701_3_dialog_content = "ฟีญ่าออกผจญภัยกับเหล่าสัตว์มหัศจรรย์♫",
  ui_story_5028_50280701_4_dialog_content = "และเคเลสไทต์ผู้ใจดี♪",
  ui_story_5028_50280701_5_dialog_content = "โล โล โล♫",
  ui_story_5028_50280701_6_dialog_content = "ดูเธออารมณ์ดีจังนะ",
  ui_story_5028_50280701_7_dialog_content = "ฮิฮิ! ฉันตื่นเต้นน่ะสิ ไม่นึกเลยว่าอีกแค่บททดสอบเดียวก็จะจบแล้ว!",
  ui_story_5028_50280701_8_dialog_content = "เป็นเพราะนายช่วยฉันแท้ ๆ เลย PlayerName! แล้วก็พวกแกด้วย ไคโลกับสัตว์มหัศจรรย์ทุกตัวทำให้ทุกอย่างราบรื่น!",
  ui_story_5028_50280701_9_dialog_content = "ฉันเองก็เซอร์ไพรส์เหมือนกัน",
  ui_story_5028_50280701_10_dialog_content = "ตอนแรกนึกว่าเธอจะทนลำบากไม่ไหวจนยอมแพ้... แล้วฉันก็จะได้รอดพ้นจากเรื่องนี้ไป",
  ui_story_5028_50280701_11_dialog_content = "ไม่นึกเลยล่ะสิว่าฉันจะมีแพสชั่นกับสัตว์มหัศจรรย์เต็มเปี่ยมแบบนี้!",
  ui_story_5028_50280701_12_dialog_content = "ถ้าเธอแก้นิสัยก้าวร้าวของตัวเองได้ล่ะก็นะ...",
  ui_story_5028_50280701_13_dialog_content = "ไม่มีทาง นั่นเป็นจุดขายของฟีญ่าเลยนะ ถ้าหายไปก็แย่เลยสิ!",
  ui_story_5028_50280701_14_dialog_content = "ก็จริงแฮะ นิสัยนั่นก็เป็นส่วนนึงที่ทำให้เธอเป็นตัวเธอ",
  ui_story_5028_50280701_15_dialog_content = "ฮิฮิ",
  ui_story_5028_50280701_16_dialog_content = "(ฉันรู้ว่าฟีญ่าเป็นคนจิตใจเมตตาและอ่อนโยน แม้จะปิดบังตัวเองด้วยบุคลิกก๋ากั่นแบบนี้)",
  ui_story_5028_50280701_16X_dialog_content = "(แต่สัตว์พวกนี้ก็รู้ว่าที่จริงเธอเป็นคนยังไง)",
  ui_story_5028_50280701_17_dialog_content = "(ถึงสัตว์มหัศจรรย์จะดูมีชีวิตที่เรียบง่าย แต่มันก็ฉลาดพอที่จะแยกแยะคนจริงใจกับคนเสแสร้งออก... และรู้ว่าใครใจดีหรือใจร้ายกับมัน)",
  ui_story_5028_50280701_18_dialog_content = "(ความสัมพันธ์อันใกล้ชิดระหว่างพวกมันกับฟีญ่าก็พิสูจน์ได้มากพอแล้ว ว่าฟีญ่าเป็นเด็กที่น่ารักและเอื้อเฟื้อ)",
  ui_story_5028_50280701_19_dialog_content = "... เอ๊ะ? ทำไมอยู่ ๆ ถึงเหม่อแบบนั้นล่ะ?",
  ui_story_5028_50280701_20_dialog_content = "หิวน้ำหรือไง? เอ้า เอาน้ำฉันไปดื่มสิ",
  ui_story_5028_50280701_21_dialog_content = "เดี๋ยวเดินอีกครึ่งวันก็น่าจะถึงบ้านของอาจารย์แล้ว อดทนอีกหน่อยนะ...",
  ui_story_5028_50280701_22_dialog_content = "โอ๊ะ! ม-ไม่ต้องหรอก ฉันสบายดี",
  ui_story_5028_50280701_23_dialog_content = "ฉันก็แค่สงสัยว่า... ถ้าการเรียนของเธอจบลง เธอคิดจะทำอะไรต่อเหรอ?",
  ui_story_5028_50280701_24_dialog_content = "แผนในอนาคตงั้นเหรอ? ก็ว่าจะเดินทางรอบโลกเพื่อศึกษาเรื่องราวทุกอย่างเกี่ยวกับสัตว์มหัศจรรย์น่ะ ฉันจะได้เขียนผลงานชิ้นเอกที่ดียิ่งกว่าหนังสือของอาจารย์!",
  ui_story_5028_50280701_25_dialog_content = "ก็สมกับเป็นเธอดีนะ...",
  ui_story_5028_50280701_26_dialog_content = "ฮิฮิ! แล้วนายล่ะ PlayerName?",
  ui_story_5028_50280701_27_dialog_content = "คงต้องหาทางทำอะไรซักอย่างกับเดรโก้ไลออนตัวนี้ล่ะมั้ง",
  ui_story_5028_50280701_28_dialog_content = "ฉันไม่อยากดูแลมังกรบินขนาดยักษ์ไปตลอดชีวิตหรอกนะ",
  ui_story_5028_50280701_29_dialog_content = "ไม่ต้องห่วงน่า เดี๋ยวจะช่วยหาทางให้นะ",
  ui_story_5028_50280701_30_dialog_content = "เดรโก้ไลออนน่าจะปล่อยโคลอสซัสไปหลังจากจบฤดูหาคู่",
  ui_story_5028_50280701_31_dialog_content = "ก็หวังว่าอย่างนั้นนะ...",
  ui_story_5028_50280701_32_dialog_content = "ที่ผ่านมาโซรอซบินวนเหนือพวกเรามาตลอด ตอนนี้คงเหนื่อยแย่...",
  ui_story_5028_50280701_33_dialog_content = "เชื่อฉันเถอะน่า ฉันมีหลักการวิทยาศาสตร์และโนว์ฮาวมาสนับสนุนทฤษฎีนะ!",
  ui_story_5028_50280701_34_dialog_content = "โล!",
  ui_story_5028_50280701_35_dialog_content = "อื้ม รู้แล้ว รู้แล้ว",
  ui_story_5028_50280701_36_dialog_content = "... หืม? นั่นอะไรน่ะ?",
  ui_story_5028_50280701_37_dialog_content = "เหมือนจะเป็น<color=#FFB400>รูปปั้น</color>บางอย่างนะ",
  ui_story_5028_50280701_38_dialog_content = "ไม่เคยเห็นรูปปั้นแบบนี้มาก่อนเลยแฮะ",
  ui_story_5028_50280701_39_dialog_content = "(น่าแปลกจริง ๆ... รูปปั้นนี้มอบความอบอุ่นและสบายใจอย่างมากมายให้กับฉัน)",
  ui_story_5028_50280701_40_dialog_content = "เอ่อ... ฉันว่าเราควรไปทำความเคารพหรือสวดภาวนาดูหน่อยนะ? รูปปั้นนี้อาจช่วยให้เธอผ่านการทดสอบอย่างราบรื่นก็ได้!",
  ui_story_5028_50280701_41_dialog_content = "ลองดูก็ไม่เสียหาย... ไปกันเลย!",
  ui_story_5028_50280701_42_dialog_content = "(เมื่อเรามุ่งหน้าเข้าใกล้รูปปั้น ความรู้สึกดี ๆ ก็ถาโถมเข้าใส่ฉันอย่างล้นหลามจนแทบตั้งตัวไม่อยู่)",
  ui_story_5028_50280701_43_dialog_content = "ฉันอาจจะไม่รู้ชื่อของคุณ แต่ได้โปรด... ช่วยอวยพรให้ฉันผ่านการทดสอบ และได้เป็นนักสัตว์วิทยามหัศจรรย์ตัวจริงด้วยเถอะ",
  ui_story_5028_50280701_44_dialog_content = "แล้วก็ช่วยอวยพรเดรโก้ไลออนให้พบรักใหม่ด้วย โซรอซจะได้กลับไปอยู่ข้างกาย PlayerName ซักที",
  ui_story_5028_50280701_45_dialog_content = "แล้วก็ช่วยอวยพรให้ไคโล...",
  ui_story_5028_50280701_46_dialog_content = "ได้โปรดเถอะ...",
  ui_story_5028_50280701_47_dialog_content = "...",
  ui_story_5028_50280701_48_dialog_content = "หืม? เดี๋ยวก่อน... ฉันว่ามันผิดปกติแล้ว",
  ui_story_5028_50280701_49_dialog_content = "ยินดีด้วยนะ ฟีญ่า!",
  ui_story_5028_50280701_50_dialog_content = "ในที่สุดเธอก็ผ่านการทดสอบจนได้ ตอนนี้เธอคือนักสัตว์มหัศจรรย์วิทยาที่เก่งกาจที่สุดในโลกแล้วล่ะ!",
  ui_story_5028_50280701_51_dialog_content = "หืม...? อาจารย์?! นี่ฉันเป็นสุดยอดนักสัตว์วิทยาแล้วจริง ๆ เหรอ?",
  ui_story_5028_50280701_52_dialog_content = "ใช่! นั่งก่อนสิ",
  ui_story_5028_50280701_53_dialog_content = "ความสำเร็จของฉันเทียบผลงานของเธอไม่ติดเลยนะ ฟีญ่า ถ้าเป็นเรื่องสัตว์มหัศจรรย์ล่ะก็ ไม่มีใครในโลกเก่งสู้เธอได้แม้แต่คนเดียว!",
  ui_story_5028_50280701_54_dialog_content = "ฝีมือของเราสองคนต่างกันฟ้ากับเหวเลยล่ะ! ฉันได้แต่หวังว่าเธอจะมีเมตตายอมรับฉันเป็นศิษย์ ฉันจะเรียนรู้สิ่งต่าง ๆ จากเธอในอนาคต!",
  ui_story_5028_50280701_55_dialog_content = "ฮิฮิ... ฉันไม่ได้เก่งขนาดนั้นหรอกน่า เอาเป็นว่าเดี๋ยวจะไปคิดดูนะ!",
  ui_story_5028_50280701_56_dialog_content = "คุณฟีญ่า",
  ui_story_5028_50280701_57_dialog_content = "หืม? ใครน่ะ?",
  ui_story_5028_50280701_58_dialog_content = "วีรกรรมของคุณเป็นที่เลื่องลือไปทั่วดินแดน และฉันก็เป็นหนึงในแฟนคลับของคุณ",
  ui_story_5028_50280701_59_dialog_content = "แฟน ๆ ของคุณพร้อมช่วยเหลือและสนับสนุนคุณในการผจญภัยครั้งต่อไปแล้ว",
  ui_story_5028_50280701_60_dialog_content = "ฟีญ่า! ฟีญ่า! ฟีญ่า!",
  ui_story_5028_50280701_61_dialog_content = "โอ้โห! ทั้งหมดนี่คือแฟนคลับของฉันเหรอเนี่ย?",
  ui_story_5028_50280701_62_dialog_content = "แหะแหะ! ยอดฝีมืออย่างฉันก็ต้องมีคนชื่นชอบอยู่แล้วนี่นะ!",
  ui_story_5028_50280701_63_dialog_content = "เดี๋ยวก่อน... เหมือนฉันจะลืมเรื่องสำคัญไปแฮะ...",
  ui_story_5028_50280701_64_dialog_content = "PlayerName! PlayerName ไปไหนแล้วล่ะ?",
  ui_story_5028_50280701_65_dialog_content = "<color=#e8d9bb>ขณะเดียวกัน...</color>",
  ui_story_5028_50280701_66_dialog_content = "หืม... ทำไมฉันถึงกลับมาที่โคลอสซัสแล้วล่ะ? นี่ฉันอยู่ไหนเนี่ย?",
  ui_story_5028_50280701_67_dialog_content = "ลูมแอมเบอร์เยอะขนาดนี้เลยเหรอ? ยอดไปเลย! นี่ฉันไม่ได้ฝันไปใช่มั้ย?",
  ui_story_5028_50280701_68_dialog_content = "จะฝันรึเปล่าก็ช่างมันเถอะ วันนี้ฉันจะใช้ลูมแอมเบอร์อัญเชิญออโรเรียนให้หมดเลย! รอบแรกสุ่มซัก 100 ทีก่อนก็แล้วกัน!",
  ui_story_5028_50280701_69_dialog_content = "<color=#e8d9bb>คึ่ก—!</color>",
  ui_story_5028_50280701_70_dialog_content = "<color=#e8d9bb>คึ่ก คึ่ก—!</color>",
  ui_story_5028_50280701_71_dialog_content = "หวา! ทำไมถึงได้ยินเสียงคนสู้กันล่ะ?",
  ui_story_5028_50280701_72_dialog_content = "ตื่นได้แล้ว เจ้าเด็กโง่!",
  ui_story_5028_50280701_73_dialog_content = "แล้วนี่มัน... มีคนดุฉันอยู่งั้นเหรอ?",
  ui_story_5028_50280701_74_dialog_content = "ข-ขอสุ่มอีกซัก 10 ทีน่า!",
  ui_story_5028_50280701_75_dialog_content = "กรร!",
  ui_story_5028_50280701_76_dialog_content = "หวา!",
  ui_story_5028_50280701_77_dialog_content = "อ-อิคลิพไซท์?!",
  ui_story_5028_50280701_78_dialog_content = "ก-เกิดอะไรขึ้นน่ะ?",
  ui_story_5028_50280701_79_dialog_content = "ฟ... ฟีญ่า? เราอยู่ที่ไหน...? แล้วอิคลิพไซท์พวกนี้มาได้ยังไง? แล้วผู้หญิงคนนั้นเป็นใครล่ะเนี่ย?!",
  ui_story_5028_50280701_80_dialog_content = "ช่างเถอะน่า ลุกขึ้นมาช่วยฉันสู้ได้แล้ว!",
  ui_story_5028_50280701_81_dialog_content = "<size=45>กรรรร!</size>",
  ui_story_5028_50280701_82_dialog_content = "ฟีญ่า!",
  ui_story_5028_50280701_83_dialog_content = "ด-ได้เลย! PlayerName ลุยกันเถอะ ไคโล!",
  ui_story_5028_50280702_1_dialog_content = "ไม่อยากเชื่อเลยว่าเราจะโดนอิคลิพไซท์โจมตี...",
  ui_story_5028_50280702_2_dialog_content = "เกิดอะไรขึ้นกันแน่นะ ตอนสุดท้ายที่จำความได้ เราก็แค่สวดภาวนากับรูปปั้นอยู่...",
  ui_story_5028_50280702_3_dialog_content = "แล้วจู่ ๆ ... ฉันก็ฝันว่าตัวเองเป็นนักสัตว์มหัศจรรย์วิทยาที่เก่งที่สุดในโลก",
  ui_story_5028_50280702_4_dialog_content = "ใช่ ฉันก็เหมือนกัน... ฉันฝันว่าตัวเองอยู่ท่ามกลางแสงสีม่วงกับสีทองระยิบระยับ...",
  ui_story_5028_50280702_5_dialog_content = "แล้วจู่ ๆ ออโรเรียนมากมายที่ฉันรู้จักก็มาอยู่ข้างกาย แม้แต่คนที่ไม่ได้ร่วมเดินทางกันแล้วก็ยังกลับมาหา",
  ui_story_5028_50280702_6_dialog_content = "พวกเธอสองคนนี่เพ้อเจ้อเก่งไม่เบานะ",
  ui_story_5028_50280702_7_dialog_content = "เมื่อกี้บอกว่าสวดภาวนากับรูปปั้นใช่มั้ย?",
  ui_story_5028_50280702_8_dialog_content = "ใช่ มีอะไรเหรอ?",
  ui_story_5028_50280702_9_dialog_content = "เธอกล้าสวดภาวนากับเทวรูปประหลาด... โดยที่ไม่รู้ว่ามันคืออะไรเนี่ยนะ?",
  ui_story_5028_50280702_10_dialog_content = "ถ้ายังควบคุมตัวเองไม่ได้ ก็อย่าเพ้อฝันว่าจะได้เป็นนักสัตว์มหัศจรรย์วิทยาเลย",
  ui_story_5028_50280702_11_dialog_content = "เธอยังพอมีเวลาเข้ารับการศึกษาภาคบังคับที่อิลลูมินา อย่างน้อยจบออกมาก็น่าจะมีโรงงานประกอบอาวุธซักที่รับเธอเข้าทำงานล่ะนะ",
  ui_story_5028_50280702_12_dialog_content = "ว่าไงนะ?!?",
  ui_story_5028_50280702_13_dialog_content = "บังอาจพูดแบบนั้นกับฉัน ยิ่งใหญ่มาจากไหนกัน?!",
