  ui_story_5028_50280702_21_dialog_content = "แต่ฉันบอกได้ว่า... ถ้าเธอยังคิดจะเป็นนักสัตว์มหัศจรรย์วิทยามืออาชีพด้วยทัศนคติที่ไร้เดียงสาและเอาความสนุกของตัวเองเป็นที่ตั้งแบบนั้น",
