  ui_story_5028_50280702_24_dialog_content = "พวกมันไม่ใช่ของเล่น ไม่ใช่เพื่อนคลายเหงา แล้วก็ไม่ใช่สัตว์ธรรมดาไร้พิษสงที่ต้องมาขอความเมตตาจากเธอ",
