  ui_story_5028_50280801_2_dialog_content = "ถึงจะใช้เวลานานซักหน่อย แต่ในที่สุดฉันก็ทำบททดสอบเพี้ยน ๆ ของนายเสร็จแล้วนะ!",
  ui_story_5028_50280801_X2_dialog_content = "แต่ถึงจะรับรองแบบนั้น แต่ไคโลก็ไม่ \"วิวัฒนาการ\" เลย เกิดอะไรขึ้นกันแน่?",
  ui_story_5028_50280801_3_dialog_content = "ขอรบกวนด้วยนะครับ...",
  ui_story_5028_50280801_4_dialog_content = "(ที่นี่... ทำไมมันเละเทะขนาดนี้ล่ะเนี่ย!)",
  ui_story_5028_50280801_5_dialog_content = "(มีหนังสือกระจัดกระจายอยู่ทุกที่... อาจารย์ของเธอคงไม่มีระเบียบเลยสินะ?!)",
  ui_story_5028_50280801_6_dialog_content = "ว่าไง อาจารย์? ให้ฉันจบหลักสูตรได้รึยัง หรือว่า...",
