  ui_story_5028_50280801_9_dialog_content = "ก็ไม่เชิง... ประมาณว่า ถึงรกแต่มันก็ยังพอจะมีระเบียบอยู่",
  ui_story_5028_50280801_10_dialog_content = "กองหนังสือที่อยู่กันมั่ว ๆ นั่น ที่จริงแล้วมีการคัดข้อมูลสำคัญออกมาเรียงอย่างดี",
  ui_story_5028_50280801_11_dialog_content = "เขาเรียงหนังสือทุกเล่มเป็นกอง ๆ แบ่งตามประเภท",
