  ui_story_5028_50280801_13_dialog_content = "แต่ดูสิ! กองนี้เป็นหนังสือเกี่ยวกับแมลง แต่สองเล่มบนสุดกลับเป็นหนังสือเรื่องสัตว์น้ำ",
  ui_story_5028_50280801_14_dialog_content = "ถึงอาจารย์หัวเถิกตัวเหม็นจะพึ่งพาไม่ค่อยได้ แต่เขาก็ไม่เคยวางหนังสือผิดแบบนี้!",
