  ui_story_5028_50280901_42_dialog_content = "นอกจากเป้าหมายของตัวเองแล้ว พวกโจรก็น่าจะจับตาดูความเคลื่อนไหวของแก๊งอื่นเหมือนกัน",
  ui_story_5028_50280901_43_dialog_content = "ยังไงซะ พวกนั้นก็สนใจแต่อาณาเขตของตัวเอง ไม่แคร์กฎหมายอะไรอยู่แล้ว",
  ui_story_5028_50280901_44_dialog_content = "เพราะงั้นเราจะจับโจรจากแก๊งไหนก็ได้มาคนนึง แล้วก็สอบปากคำเค้นข้อมูลดู เผื่อว่ามันจะรู้เรื่องวิค",
  ui_story_5028_50280901_45_dialog_content = "น่าจะเวิร์กแหละ แต่ว่า... เราจะไปหาโจรจากไหนดีล่ะ?",
  ui_story_5028_50280901_46_dialog_content = "หาโจรจากไหนงั้นเหรอ?",
  ui_story_5028_50280901_47_dialog_content = "ไม่ยากเลย!",
  ui_story_5028_50280901_48_dialog_content = "ฟีญ่ากับ PlayerName ก็แค่เล่นละครเป็นนักเดินทางที่รวยแล้วก็งี่เง่าไงล่ะ!",
  ui_story_5028_50280901_49_dialog_content = "เริ่มจาก...",
  ui_story_5028_50280901_50_dialog_content = "เดี๋ยวนะ... ย-อย่าบอกนะว่า...?",
