  ui_story_5028_50280901_X59_dialog_content = "...",
  ui_story_5028_50280901_X60_dialog_content = "บ้าที่สุดดดดด!!!",
  ui_story_5028_50280901_59_dialog_content = "<color=#e8d9bb>หลังจากนั้นซักพัก...</color>",
  ui_story_5028_50280901_60_dialog_content = "แอปเปิลเชื่อม! ไทยากิ! ของอร่อยจากเกาะเมฆา!",
