  ui_story_5028_50280901_70_dialog_content = "ด้วยความยินดี คุณผู้หญิง!",
  ui_story_5028_50280901_71_dialog_content = "(ได้โปรดเถอะ... นั่นมันเท่ากับค่าใช้จ่าย 10 วันแล้วนะ...)",
  ui_story_5028_50280901_72_dialog_content = "...",
  ui_story_5028_50280901_73_dialog_content = "(หมอนั่น กำลังจ้องมาทางเรางั้นเหรอ?)",
  ui_story_5028_50280901_74_dialog_content = "เรากำลังโดนจับตามองอยู่ ในที่สุดเราก็เป็นเป้าหมายพวกโจรแล้วล่ะ",
  ui_story_5028_50280901_75_dialog_content = "มาได้จังหวะดีจริง ๆ ฉันกินขนมจะเสร็จพอดี! ได้เวลาดำเนินแผนขั้นต่อไปแล้ว",
