  ui_story_5028_50280901_77_dialog_content = "อา อร่อยจริง ๆ นะเนี่ย! ต่อไปเรามาช้อปปิ้งกันหน่อยดีมั้ย?",
  ui_story_5028_50280901_78_dialog_content = "แน่นอนว่าคุณจะซื้อทุกอย่างที่ฉันอยากได้ใช่มั้ย?",
  ui_story_5028_50280901_79_dialog_content = "น-นี่มันใช่แผนขั้นต่อไปจริง ๆ เหรอ?!",
  ui_story_5028_50280901_80_dialog_content = "<size=45>อะแฮ่ม!!!</size>",
  ui_story_5028_50280901_81_dialog_content = "โอ๊ย! ก็ได้ ก็ได้ เลิกเตะฉันได้แล้ว!",
