  ui_story_5028_50280901_86_dialog_content = "(ขอโทษนะไวซ์ ฉันผลาญเงินจนหมดอีกแล้ว...)",
  ui_story_5028_50280901_87_dialog_content = "(ยกโทษให้ฉันด้วยนะโซรอซ กำหนดซ่อมบำรุงเดือนหน้า... ขอเลื่อนไปก่อนก็แล้วกัน...)",
  ui_story_5028_50280901_88_dialog_content = "...",
  ui_story_5028_50280901_89_dialog_content = "ดูโน่นสิ ผู้ชายคนนั้นหน้าเหมือน PlayerName เลยเนอะ?",
