  ui_story_5028_50280901_97_dialog_content = "<color=#e8d9bb>นอกเมือง</color>",
  ui_story_5028_50280901_98_dialog_content = "(ถึงทำทีบอกว่าจะช้อปปิ้ง แต่ที่จริงฟีญ่าพยายามพาฉันออกไปแถวชานเมือง ซึ่งเป็นที่ที่คนไม่เยอะ...)",
