  ui_story_5028_50280901_107_dialog_content = "เอาล่ะ ลูกเศรษฐีทั้งสองคน ช่วยมาเดินเล่นกับฉันหน่อยได้มั้ย?",
  ui_story_5028_50280901_108_dialog_content = "ไม่มีทางเลือกแล้วสินะ PlayerName... เราตามเขาไปก่อนเถอะ",
  ui_story_5028_50280901_109_dialog_content = "อะไรนะ?!",
  ui_story_5028_50280901_110_dialog_content = "เห็นมั้ยพวก? ขนาดสาวน้อยคนนี้ยังเข้าใจเลย เอาล่ะ เอามือไพล่หลังได้แล้ว จะได้มัดง่าย ๆ หน่อย...",
