  ui_story_5028_50280901_118_dialog_content = "(นั่งชมการแสดงอย่างสบายใจเถอะน่า เชื่อฉันสิ! ตอนนี้เราต้องอดทนไปก่อน...)",
  ui_story_5028_50280901_119_dialog_content = "วันนี้เป็นวันโชคดีของเราจริง ๆ สหาย! ถึงแก๊งอื่นจะชิงตัดหน้าลักพาตัวเป้าหมายของเราไป...",
