  ui_story_5028_50280901_141_dialog_content = "วิคอยู่ที่ไหน?",
  ui_story_5028_50280901_142_dialog_content = "รีบ ๆ ตอบมาได้แล้ว บีบคอพวกแกแบบนี้มันเหนื่อยนะรู้มั้ย?",
