  ui_story_5028_50281001_45_dialog_content = "แล้วทำไมเธอไม่ไปช่วยเขาล่ะ?",
  ui_story_5028_50281001_46_dialog_content = "ฉันขี้เกียจแก้มัดเขาน่ะสิ แล้วถ้าต้องแบกหมอนั่นมาตรงนี้มันก็ยิ่งวุ่นวายเข้าไปอีก",
  ui_story_5028_50281001_47_dialog_content = "นี่! เธอจะขี้เกียจทำทุกเรื่องเลยหรือไง?!",
  ui_story_5028_50281001_48_dialog_content = "แล้วฉันก็ไม่มั่นใจด้วย ว่าถ้าแก้มัดเขาแล้ว เขาจะก่อเรื่องวุ่นวายมากกว่านี้รึเปล่า",
  ui_story_5028_50281001_49_dialog_content = "คนป้ำ ๆ เป๋อ ๆ แบบนั้นปกป้องสัตว์มหัศจรรย์ได้ยังไง",
  ui_story_5028_50281001_50_dialog_content = "ควรปล่อยให้เป็นหน้าที่ของมืออาชีพมากกว่านะ",
  ui_story_5028_50281001_51_dialog_content = "อย่างน้อยเราก็คิดเหมือนกันเรื่องนึง อาจารย์ของเราพึ่งพาไม่ได้เลย",
  ui_story_5028_50281001_52_dialog_content = "แต่ในฐานะนักสัตว์มหัศจรรย์วิทยา ฉันจะพยายามทำทุกอย่างเพื่อปกป้องสัตว์มหัศจรรย์ในโลกแทนเขา!",
  ui_story_5028_50281001_53_dialog_content = "หึ ก็ตามใจ",
  ui_story_5028_50281001_54_dialog_content = "วิคอยู่ในนั้นแหละ ถ้าอยากช่วยเขาก็ไปเลย",
  ui_story_5028_50281001_55_dialog_content = "อย่ามาเกะกะฉันก็พอ",
  ui_story_5028_50281001_56_dialog_content = "กรอดด... ยัยนี่ดูถูกฉันอีกแล้ว!",
  ui_story_5028_50281001_57_dialog_content = "ให้ตายสิ... ซักวันนึงฉันจะต้องเก่งจนเธอทึ่งให้ได้!",
  ui_story_5028_50281001_58_dialog_content = "โล!!!",
  ui_story_5028_50281001_59_dialog_content = "แกก็คิดแบบนั้นเหมือนกันใช่มั้ย ไคโล?",
  ui_story_5028_50281001_60_dialog_content = "ไปพาอาจารย์ออกมากันเถอะ!",
  ui_story_5028_50281001_61_dialog_content = "<color=#e8d9bb>ส่วนลึกของฐานทัพแกรี่</color>",
  ui_story_5028_50281001_62_dialog_content = "อาจารย์วิค!",
  ui_story_5028_50281001_63_dialog_content = "ให้ตายสิ คราวนี้ดูไม่จืดเลยนะ อาจารย์...",
  ui_story_5028_50281001_64_dialog_content = "เอาล่ะ ฉันจะแก้มัดให้นะ",
  ui_story_5028_50281001_65_dialog_content = "โอ้! ฉันรู้อยู่แล้วว่าเธอจะต้องมาช่วย!",
  ui_story_5028_50281001_66_dialog_content = "มาได้จังหวะเหมาะพอดีเลย แขนฉันโดนมัดจนชาไปหมดแล้ว...",
  ui_story_5028_50281001_67_dialog_content = "แล้วชายหนุ่มคนนี้เป็นใครกันล่ะเนี่ย?",
