  ui_story_5028_50281001_69_option_content = "เป็นเคเลสไทต์คนสุดท้ายที่ฟีญ่าจับได้ครับ",
  ui_story_5028_50281001_70_dialog_content = "อื้ม อื้ม~",
  ui_story_5028_50281001_71_dialog_content = "นี่คือเคเลสไทต์ หนึ่งในสัตว์มหัศจรรย์ที่หายากที่สุดเท่าที่ฉันเคยจับได้!",
  ui_story_5028_50281001_72_dialog_content = "ตอนนี้เหลือแค่คนเดียวแล้วด้วย!",
  ui_story_5028_50281001_73_option_content = "ผมเป็นเพื่อนของฟีญ่า",
  ui_story_5028_50281001_74_dialog_content = "ใช่แล้ว! เขาเป็นหนึ่งในสหายสัตว์มหัศจรรย์ของฉัน!",
  ui_story_5028_50281001_75_dialog_content = "เคเลสไทต์ที่เหลืออยู่เพียงคนเดียวในโลก!",
  ui_story_5028_50281001_76_dialog_content = "โอ้? แล้วเธอก็จับเขาได้ด้วยเหรอ?",
  ui_story_5028_50281001_77_dialog_content = "แน่นอน!",
  ui_story_5028_50281001_78_dialog_content = "ไม่ใช่แค่นั้นนะ—ฉันยังทำบททดสอบทุกข้อเสร็จแล้วด้วย",
  ui_story_5028_50281001_79_dialog_content = "ยอดมาก",
  ui_story_5028_50281001_80_dialog_content = "แน่นอน ถ้าทำเรื่องจิ๊บจ๊อยพวกนั้นไม่ได้ ฉันจะเรียกตัวเองว่าเป็นนักสัตว์มหัศจรรย์วิทยาได้ยังไงกัน",
  ui_story_5028_50281001_81_dialog_content = "การที่เธอเจอเคเลสไทต์ ก็หมายความว่าแผนของฉันยังมีหวัง",
  ui_story_5028_50281001_82_dialog_content = "แผนอะไรเหรอ?",
  ui_story_5028_50281001_83_dialog_content = "ภารกิจสุดท้ายเพื่อที่เธอจะได้จบหลักสูตร นั่นก็คือการหยุดแผนชั่วของแกรี่!",
  ui_story_5028_50281001_84_dialog_content = "เดี๋ยวนะ!",
  ui_story_5028_50281001_85_dialog_content = "ไหนบอกว่าผ่านบททดสอบทั้งหมดแล้วฉันจะได้จบหลักสูตรไง?",
  ui_story_5028_50281001_86_dialog_content = "ปกติแล้วเวลาทำภารกิจทั้งหมดสำเร็จ เธอก็จะได้ภารกิจลับ การผจญภัยส่วนใหญ่มันก็เป็นแบบนั้นไม่ใช่หรือไง?",
  ui_story_5028_50281001_87_dialog_content = "ไร้ความรับผิดชอบจริง ๆ! ว่าแล้วว่าฉันเชื่ออะไรนายไม่ได้!",
  ui_story_5028_50281001_88_dialog_content = "ทั้งสองคนคุยอะไรกันน่ะ...",
  ui_story_5028_50281001_89_dialog_content = "ช่วยอธิบายหน่อยได้มั้ยว่ามันเกิดอะไรขึ้นกันแน่?",
  ui_story_5028_50281001_90_dialog_content = "แล้วก็ คุณมีเรื่องอะไรกับแกรี่เหรอ? เขาถึงลักพาตัวคุณมาแบบนี้?",
  ui_story_5028_50281001_91_dialog_content = "เรื่องมันยาวน่ะ...",
  ui_story_5028_50281001_92_dialog_content = "แต่ก่อนแกรี่เคยเป็นเพื่อนสนิทของฉัน",
  ui_story_5028_50281001_93_dialog_content = "ความหลงใหลในสัตว์มหัศจรรย์ทำให้สังคมมองฉันเป็นคนประหลาด และผู้คนก็ไม่กล้าสุงสิงกับคนอย่างฉัน",
  ui_story_5028_50281001_94_dialog_content = "แต่สำหรับแกรี่ พอเขารู้ว่าฉันเชี่ยวชาญเรื่องสัตว์มหัศจรรย์ เขาก็เข้ามาขอความรู้ตลอดเวลาด้วยความหลงใหล",
  ui_story_5028_50281001_95_dialog_content = "ตอนแรกฉันคิดว่าได้เจอกับคนที่มีอุดมการณ์เดียวกัน เพื่อนร่วมอาชีพที่ต้องการพัฒนาความรู้ในสายวิชา",
