  ui_story_5028_50281002_14_dialog_content = "มีเรื่องสำคัญอะไรที่ทำให้เธอถึงกับต้องทอดทิ้งอาจารย์ให้พวกโจรกัน?",
  ui_story_5028_50281002_15_dialog_content = "ชีร่า เด็กผู้น่าสงสาร ความหลงใหลในสัตว์มหัศจรรย์ของเธอนั้นไม่ได้น้อยไปกว่าพวกเราเลย",
  ui_story_5028_50281002_16_dialog_content = "น่าเสียดายที่ความพยายามของเธอมักจะถูกขัดขวางด้วยโชคร้ายนิด ๆ หน่อย ๆ เสมอ สังเกตเห็นอะไรแปลก ๆ จากตัวเธอบ้างมั้ย?",
