  ui_story_5028_50281002_25_dialog_content = "แน่นอนว่านี่เป็นอุปสรรคอันหนักหนาสำหรับชีร่า แต่ไม่มีอะไรหยุดความหลงใหลในสายอาชีพนี้ของเธอได้",
