  ui_story_5028_50281102_103_dialog_content = "พวกมันจับไคโลของฉันไปแล้ว ตัวอื่นที่เหลือก็สู้กับโจรพวกนี้ไม่ได้ด้วย",
  ui_story_5028_50281102_104_dialog_content = "ลองถามชีร่าหรือยัง? เห็นแปลก ๆ แบบนั้น แต่ที่จริงเธอเก่งมากนะ ไม่แน่อาจมีวิธีก็ได้",
  ui_story_5028_50281102_105_dialog_content = "ชีร่า คิดอะไรออกมั้ย? มีวิธีใช้พลังของสัตว์พวกนี้เพื่อหนีหรือเปล่า?",
  ui_story_5028_50281102_106_dialog_content = "แทนที่จะคิดหาวิธีสั่งให้สัตว์ที่น่าสงสารเหล่านี้ต่อสู้กับโจรชั่ว...",
  ui_story_5028_50281102_107_dialog_content = "มาคิดหาวิธีแก้มัดให้ตัวเองยังจะดีซะกว่า",
  ui_story_5028_50281102_108_dialog_content = "ถ้าฉันฟื้นพลังแล้ว จะฉีกพวกมันเป็นชิ้น ๆ ก็ไม่ยากหรอก",
  ui_story_5028_50281102_109_dialog_content = "แต่ถ้าพวกมันไม่ช่วยเราเลย... วิค มีวิธีบ้างมั้ย?",
  ui_story_5028_50281102_110_dialog_content = "อย่าเพิ่งใจร้อนสิ PlayerName",
  ui_story_5028_50281102_111_dialog_content = "เราอาจทำอะไรไม่ได้ในตอนนี้ แต่นายใช้ความสามารถของเคเลสไทต์ตรวจดูรอบ ๆ นี้ได้นี่",
