  ui_story_5028_50281102_113_dialog_content = "เอางั้นเลยเหรอ? ผมเนี่ยนะ?",
  ui_story_5028_50281102_114_dialog_content = "จะพยายามก็แล้วกัน",
  ui_story_5028_50281102_115_option_content = "บังคับเชื่อมกระแสจิต!",
  ui_story_5028_50281102_116_dialog_content = "...",
  ui_story_5028_50281102_117_dialog_content = "(มีโจรลาดตระเวนอยู่แถวนี้...)",
  ui_story_5028_50281102_118_dialog_content = "(สัตว์มหัศจรรย์ถูกขังอยู่ในกรง)",
  ui_story_5028_50281102_119_dialog_content = "(มีสัตว์มหัศจรรย์ที่ดูเหมือนไคโลเต็มไปหมดเลย?!)",
