  ui_story_5028_50281102_121_dialog_content = "ให้ตายสิ เขาจับได้จริงเหรอเนี่ย?",
  ui_story_5028_50281102_122_dialog_content = "แต่อย่าเพิ่งกังวลไป ถ้าเขายังปลุกความสามารถของไคโลไม่ได้ ก็ไม่มีอะไรต้องห่วง",
  ui_story_5028_50281102_123_dialog_content = "ได้ ผมจะตรวจดูรอบ ๆ อีกที เหมือนมีอะไรบางอย่างขยับอยู่ไกล ๆ",
