  ui_story_5028_50281201_89_dialog_content = "เป็นผู้ชายที่น่ารังเกียจจริง ๆ เผาถ้ำนี่ไปเลยดีกว่าน่า",
  ui_story_5028_50281201_90_dialog_content = "โอ๊ะโอ ไม่ได้ ๆ ไม่ได้เด็ดขาด",
  ui_story_5028_50281201_91_dialog_content = "ในนี้มีพวกไคโลที่แกรี่จับมาเต็มไปหมด! ทำแบบนั้นพวกมันแย่แน่!",
  ui_story_5028_50281201_92_dialog_content = "อะไรเนี่ย? มีพวกโง่มาเพิ่มอีกงั้นเรอะ? เพื่อนของเจ้าเด็กถั่วงอกนี่สินะ",
  ui_story_5028_50281201_93_dialog_content = "อย่ามาเรียกฉันว่าถั่วงอกนะ!",
  ui_story_5028_50281201_94_dialog_content = "ทำไมถึงกระตือรือร้นที่จะมาช่วยสัตว์เดรัจฉานพวกนี้กันจัง?",
  ui_story_5028_50281201_95_dialog_content = "พวกเขาไม่ใช่สัตว์เดรัจฉาน พวกเขาเป็นเพื่อนและสหายคู่ใจของเรา!",
  ui_story_5028_50281201_96_dialog_content = "สหายคู่ใจ? ฮ่าฮ่า! ไม่ พวกมันไม่ใช่สหาย พวกมันเป็นสัตว์เดรัจฉาน",
  ui_story_5028_50281201_97_dialog_content = "ไปมองว่ามันเป็นเพื่อน เธอคิดไปเองฝ่ายเดียวนะ",
  ui_story_5028_50281201_98_dialog_content = "พอถึงคราวขึ้นมา สัตว์ก็เป็นแค่สัตว์อยู่วันยังค่ำ",
  ui_story_5028_50281201_99_dialog_content = "เมื่อไหร่ที่เธอหมดผลประโยชน์ พวกมันก็จะทอดทิ้งเธอ และฉีกเธอเป็นชิ้น ๆ",
  ui_story_5028_50281201_100_dialog_content = "คนบ้า! คนเสียสติ!",
  ui_story_5028_50281201_101_dialog_content = "นี่ แม่หนูน้อย",
  ui_story_5028_50281201_102_dialog_content = "ฉันชื่อฟีญ่า!",
  ui_story_5028_50281201_103_dialog_content = "อะไรก็ช่าง ตาลุงนั่นเพี้ยนไปแล้ว ไม่รู้อะไรทำให้แค้นแบบนี้",
  ui_story_5028_50281201_104_dialog_content = "จะพูดโน้มน้าวคนหลงผิดยังไงก็ไม่ได้ผลหรอก วิธีเดียวที่พวกนั้นเข้าใจก็คือ...",
  ui_story_5028_50281201_105_dialog_content = "คือ?",
  ui_story_5028_50281201_106_dialog_content = "ก็คือ...?",
  ui_story_5028_50281201_107_dialog_content = "การโน้มน้าวด้วยกำลังไงล่ะ",
  ui_story_5028_50281201_108_dialog_content = "ว้าว คำตอบนี้มันชีร่าสุด ๆ",
  ui_story_5028_50281201_109_dialog_content = "คิดจะสู้งั้นเรอะ?",
  ui_story_5028_50281201_110_dialog_content = "ฮ่า! เจ๋งเป้ง",
  ui_story_5028_50281201_111_dialog_content = "ไม่ว่าจะพยายามซักกี่ครั้ง ยังไงแกก็เป็นพวกขี้แพ้",
  ui_story_5028_50281201_112_dialog_content = "กรรรร!!",
  ui_story_5028_50281202_1_dialog_content = "ไคโล จัดการซะ!",
  ui_story_5028_50281202_2_dialog_content = "โล!",
  ui_story_5028_50281202_3_dialog_content = "เชื่องช้า เงอะงะ ไม่ทันกินหรอก",
  ui_story_5028_50281202_4_dialog_content = "กรร!",
  ui_story_5028_50281202_5_dialog_content = "เรวี่ ปกป้องฟีญ่าด้วย!",
  ui_story_5028_50281202_6_dialog_content = "ฉันไม่ปล่อยแกไปแน่!",
  ui_story_5028_50281202_7_dialog_content = "คาเรนนีน่า!",
  ui_story_5028_50281202_8_dialog_content = "เป็นไงล่ะ? เพื่อนฉันฝีมือดีใช่ป่าว?",
  ui_story_5028_50281202_9_dialog_content = "เอ่อ...",
  ui_story_5028_50281202_10_dialog_content = "ลูกไม้แค่นี้ก็พอจะกู้หน้าได้ล่ะนะ",
  ui_story_5028_50281202_11_dialog_content = "ต้องบอกว่าออโรเรียนพวกนี้ป่วนใช่เล่น",
  ui_story_5028_50281202_12_dialog_content = "งั้นลองนี่หน่อยเป็นไง?",
  ui_story_5028_50281202_13_dialog_content = "แส้นั่น มัน<color=#FFB400>เรืองแสง</color>!",
  ui_story_5028_50281202_14_dialog_content = "ทุกคน ระวังนะ!",
  ui_story_5028_50281202_15_dialog_content = "โล... โล...!",
  ui_story_5028_50281202_16_dialog_content = "ไคโล? ไคโล!",
  ui_story_5028_50281202_17_dialog_content = "เปโกะ...",
  ui_story_5028_50281202_18_dialog_content = "ตาแก่โรคจิต! แกจะทำอะไรน่ะ?!",
  ui_story_5028_50281202_19_dialog_content = "ใจเย็นสิ เจ้าหนู",
  ui_story_5028_50281202_20_dialog_content = "เดี๋ยวเธอก็จะได้เห็นเพื่อนที่น่ารักพวกนี้แหวกท้องเธอเองแหละ!",
  ui_story_5028_50281202_21_dialog_content = "พวกเขาไม่มีวันทำแบบนั้นหรอก!",
  ui_story_5028_50281202_22_dialog_content = "โจมตีแส้เขาเร็วเข้า!",
  ui_story_5028_50281202_23_dialog_content = "รู้แล้วล่ะน่า!",
  ui_story_5028_50281202_24_dialog_content = "อ๊ะ!",
  ui_story_5028_50281202_25_dialog_content = "หมอนี่ควบคุมอิคลิพไซท์เยอะแค่ไหนกันเนี่ย...",
  ui_story_5028_50281202_26_dialog_content = "ข้อดีของอิคลิพไซท์คือมันมีมากได้เท่าที่ต้องการ",
  ui_story_5028_50281202_27_dialog_content = "ต่อให้ตายไปหมด มันก็จะมีตัวใหม่มาแทนเรื่อย ๆ",
  ui_story_5028_50281202_28_dialog_content = "ทุกคน พร้อมกันนะ!",
  ui_story_5028_50281202_29_dialog_content = "<color=#e8d9bb>โล!</color>",
  ui_story_5028_50281202_30_dialog_content = "นั่นใช่เสียงไคโลรึเปล่า?",
  ui_story_5028_50281202_31_dialog_content = "<color=#e8d9bb>โล... โล!</color>",
  ui_story_5028_50281202_32_dialog_content = "ม-ไม่ใช่ นั่นไม่ใช่ไคโล!",
  ui_story_5028_50281202_33_dialog_content = "เสียงร้องดังมาจากรอบตัวเรา!",
  ui_story_5028_50281202_34_dialog_content = "ดูท่าไม่ดีแล้ว...",
  ui_story_5028_50281202_35_dialog_content = "เป้าหมายของเขาไม่ใช่แค่ไคโลของฟีญ่า แต่เป็นไคโลทั้งหมดที่ถูกจับมาที่ฐาน!",
  ui_story_5028_50281202_36_dialog_content = "โอย แบบนี้แย่แน่",
  ui_story_5028_50281202_37_dialog_content = "จะปล่อยให้พวกเขาถูกขังไม่ได้แล้ว ต้องมีคนไปช่วย!",
  ui_story_5028_50281202_38_dialog_content = "พี่ชีร่า!",
  ui_story_5028_50281202_39_dialog_content = "หืม?",
  ui_story_5028_50281202_40_dialog_content = "คุณเรียกตัวเองว่าผู้เชี่ยวชาญด้านสัตว์มหัศจรรย์ ใช่มั้ย?",
  ui_story_5028_50281202_41_dialog_content = "ตอนนี้คุณบาดเจ็บ ก็ไม่ต้องสนใจเรื่องการต่อสู้หรอก ช่วยพาพวกเขาออกไปจากที่นี่เถอะ!",
  ui_story_5028_50281202_42_dialog_content = "ใกล้จะตายกันอยู่แล้ว ยังจะห่วงเจ้าไคโลเพื่อนรักอีกเรอะ?",
  ui_story_5028_50281202_43_dialog_content = "ช่างเป็นกลุ่มคนที่พิลึกดีแท้",
  ui_story_5028_50281202_44_dialog_content = "กรร!",
  ui_story_5028_50281202_45_dialog_content = "พวกเรา ลุย!",
  ui_story_5028_50281202_46_dialog_content = "อัก!",
  ui_story_5028_50281202_47_dialog_content = "มาดูกันว่าฉันจะสอยได้กี่ตัว หนึ่ง สอง สาม...",
  ui_story_5028_50281202_48_dialog_content = "จัดการได้เพียบเลยล่ะ",
  ui_story_5028_50281202_49_dialog_content = "ช้าไป! ต้องเผาทีเดียวให้เกลี้ยงเลย",
  ui_story_5028_50281202_50_dialog_content = "งั้นเหรอ? มาวัดกันหน่อยมั้ยว่าใครจะจัดการเหยื่อได้เยอะกว่ากัน",
  ui_story_5028_50281202_51_dialog_content = "โล โล!",
  ui_story_5028_50281202_52_dialog_content = "วิคไม่เคยบอกเหรอ? ว่าสัตว์มหัศจรรย์น่ะ กลัวฉัน",
  ui_story_5028_50281202_53_dialog_content = "ถ้าอย่างนั้นฉันขอรับรองกับเธอในฐานะผู้เชี่ยวชาญ ว่ามันจะไม่เกิดขึ้นอีก!",
  ui_story_5028_50281202_54_dialog_content = "ว่าไงนะ?",
  ui_story_5028_50281202_55_dialog_content = "ออกมา เดรโก้ไลออน!",
  ui_story_5028_50281202_56_dialog_content = "กรร—",
  ui_story_5028_50281202_57_dialog_content = "(ฟีญ่า... เรียกเดรโก้ไลออนมา)",
  ui_story_5028_50281202_58_dialog_content = "กรร...",
  ui_story_5028_50281202_59_dialog_content = "ขอโทษที่ฝืนใจแกนะ แต่ได้โปรด...",
  ui_story_5028_50281202_60_dialog_content = "ช่วยชีร่าค้นหาสัตว์มหัศจรรย์ตัวอื่นในป่า แล้วพาพวกเขาออกไปจากที่นี่ที!",
  ui_story_5028_50281202_61_dialog_content = "พี่ชีร่า!",
  ui_story_5028_50281202_62_dialog_content = "...",
  ui_story_5028_50281202_63_dialog_content = "(ชีร่าค่อย ๆ เข้าไปใกล้เดรโก้ไลออน...)",
  ui_story_5028_50281202_64_dialog_content = "...!",
  ui_story_5028_50281202_65_dialog_content = "(ยอดเลย! มันยอมรับเธอด้วย!)",
  ui_story_5028_50281202_66_dialog_content = "นี่เป็นเรื่องจริงเหรอ...",
  ui_story_5028_50281202_67_dialog_content = "ขอบคุณเธอจริง ๆ นะ \"นักสัตว์มหัศจรรย์วิทยาฟีญ่า\"!",
  ui_story_5028_50281202_68_dialog_content = "งั้นก็ไปได้แล้ว! เร็วเข้า!",
  ui_story_5028_50281202_69_dialog_content = "ฮ่าฮ่าฮ่าฮ่า!",
  ui_story_5028_50281202_70_dialog_content = "เขาหัวเราะทำไมน่ะ?",
  ui_story_5028_50281202_71_dialog_content = "พวกแกนี่มันงี่เง่าจริง ๆ เล้ย",
  ui_story_5028_50281202_72_dialog_content = "นำขบวนสัตว์ร้ายกับเด็กเมื่อวานซืนมาหยุดฉันงั้นเหรอ?",
  ui_story_5028_50281202_73_dialog_content = "ที่จริงก็อยากจะเก็บไฮไลต์ไว้ตอนสุดท้ายนะ แต่คราวนี้คงต้องยกเว้น...",
  ui_story_5028_50281202_74_dialog_content = "จะเอามาโชว์ก่อนก็แล้วกัน",
  ui_story_5028_50281202_75_dialog_content = "ออกมา",
  ui_story_5028_50281202_76_dialog_content = "โล...",
  ui_story_5028_50281202_77_dialog_content = "นั่นใช่เสียงไคโลรึเปล่า...?",
  ui_story_5028_50281202_78_dialog_content = "ไคโลตัวเมื่อกี้เหรอ?",
  ui_story_5028_50281202_79_dialog_content = "แค่นี้ฉันไม่กลัวหรอกน่า!",
  ui_story_5028_50281202_80_dialog_content = "โล!",
  ui_story_5028_50281202_81_dialog_content = "เอ๊ะ—?!",
  ui_story_5028_50281202_82_dialog_content = "ท-ทำไม พวกมันหน้าตาเหมือนอิคลิพไซท์เลยล่ะ?",
  ui_story_5028_50281202_83_dialog_content = "แถมยังเสียงเหมือนไคโลด้วย?",
  ui_story_5028_50281202_84_dialog_content = "โล โล! โล!",
  ui_story_5028_50281202_85_dialog_content = "เจ้าตัวนี้ ก็คือไคโลตัวเมื่อกี้แหละ",
  ui_story_5028_50281202_86_dialog_content = "พลังที่แข็งแกร่งที่สุดของไคโล คือ<color=#FFB400>การเปลี่ยนแปลงรูปร่าง</color>",
  ui_story_5028_50281202_87_dialog_content = "แค่เพียงให้กำลังใจเล็กน้อย ไคโลก็สามารถแปลงร่างเป็นสิ่งมีชีวิตได้ทุกชนิด และใช้ความสามารถของสิ่งนั้นได้",
  ui_story_5028_50281202_88_dialog_content = "เรื่องสำคัญขนาดนี้ ทำไมเพิ่งมาบอกล่ะ!?",
  ui_story_5028_50281202_89_dialog_content = "เอ่อ ฉันนึกไม่ถึงน่ะ ว่าไคโลจะใช้ความสามารถนี้ในตอนที่มันหวาดกลัวได้ด้วย",
  ui_story_5028_50281202_90_dialog_content = "เพราะที่จริงแล้ว ไคโลจะทำแบบนั้นเพื่อปกป้องสหายที่เขาเชื่อใจเท่านั้น",
  ui_story_5028_50281202_91_dialog_content = "มันเกินความคาดหมายจริง ๆ นะ...",
  ui_story_5028_50281202_92_dialog_content = "แล้วนี่มันใช่เวลามายิ้มมั้ยล่ะ?",
  ui_story_5028_50281202_93_dialog_content = "เจ้านั่นน่ากลัวชะมัด! เราจะรับมือยังไงได้?",
  ui_story_5028_50281202_94_dialog_content = "นายถามถูกคนแล้วล่ะ",
  ui_story_5028_50281202_95_dialog_content = "ไคโลน่ะ ยึดมั่นในความเชื่อใจและภักดีมาก ถ้ามันเชื่อใจใคร โลกนี้ก็อยู่ในกำมือเขา",
  ui_story_5028_50281202_96_dialog_content = "และแน่นอน สิ่งเดียวที่จะเอาชนะไคโลได้ ก็คือไคโลด้วยกัน",
  ui_story_5028_50281301_1_dialog_content = "โล!",
  ui_story_5028_50281301_2_dialog_content = "โล โล!",
  ui_story_5028_50281301_3_dialog_content = "บ้าน่า! ทำไมเจ้านี่ถึงแข็งแกร่งขนาดนี้!",
  ui_story_5028_50281301_4_dialog_content = "จงดิ้นรนให้มากกว่านี้ จดจำความหวาดกลัวในวันนี้ให้ลึกลงไปในจิตใจของพวกแก!",
  ui_story_5028_50281301_5_dialog_content = "จากนั้นฉันก็จะปล่อยให้สัตว์เดรัจฉานพวกนี้ออกอาละวาดให้ทั่วแอสตรา",
  ui_story_5028_50281301_6_dialog_content = "ฮ่าฮ่า... ฮ่าฮ่าฮ่าฮ่า!",
  ui_story_5028_50281301_7_dialog_content = "ลาก่อน เจ้าหนู",
  ui_story_5028_50281301_8_dialog_content = "เอาล่ะ PlayerName!",
  ui_story_5028_50281301_9_dialog_content = "ใช้พลังของนายสิ แสดงให้ไคโลเห็นว่าฟีญ่าเชื่อใจมันแค่ไหน!",
  ui_story_5028_50281301_10_dialog_content = "หา? พลังของผม?",
  ui_story_5028_50281301_11_dialog_content = "ใช่ พลังจิตของนายไง พยายามคิดเข้าสิ!",
  ui_story_5028_50281301_12_dialog_content = "(พลังของฉัน...)",
  ui_story_5028_50281301_13_dialog_content = "(พลังของฉันทำได้แค่รับรู้และช่วยให้คนอื่นพูดคุยกันได้)",
  ui_story_5028_50281301_14_dialog_content = "(พูดคุยกัน แต่... ฟีญ่าสื่อสารกับไคโลไม่ได้นี่นา?!)",
  ui_story_5028_50281301_15_dialog_content = "พูดง่าย ๆ ก็คือ ลองอ่านความคิดและความรู้สึกของไคโล แล้วส่งมันไปให้ฟีญ่าสิ",
  ui_story_5028_50281301_16_dialog_content = "ให้ฟีญ่าจัดการที่เหลือเอง!",
  ui_story_5028_50281301_17_dialog_content = "เอ๊ะ? ผมอ่านความคิดของไคโลได้ด้วยเหรอ?",
  ui_story_5028_50281301_18_dialog_content = "ได้อยู่แล้ว อย่าลืมสิว่านายเป็นชาวเคเลสไทต์!",
  ui_story_5028_50281301_19_dialog_content = "ได้เลย ผมจะลองดูนะ!",
  ui_story_5028_50281301_20_option_content = "บังคับเชื่อมกระแสจิต!",
  ui_story_5028_50281301_21_dialog_content = "ฉันต้องอ่านความคิดของไคโลให้ได้...",
  ui_story_5028_50281301_22_dialog_content = "โล โล! โล!",
  ui_story_5028_50281301_23_dialog_content = "มันหวาดกลัวมาก มีพลังบางอย่างที่มันยังไม่ได้ใช้... แต่ดูเหมือนว่าถูกขัดขวางไม่ให้ใช้",
  ui_story_5028_50281301_24_dialog_content = "โล! โล!",
  ui_story_5028_50281301_25_dialog_content = "ความรู้สึกนี้ มันอยากจะปกป้องอะไรซักอย่างงั้นเหรอ?",
  ui_story_5028_50281301_26_dialog_content = "ปกป้อง... ปกป้อง?",
  ui_story_5028_50281301_27_dialog_content = "ฟีญ่า! ไคโลต้องการปกป้องเธอ!",
  ui_story_5028_50281301_28_dialog_content = "หา?!",
  ui_story_5028_50281301_29_dialog_content = "โล โล! โล!",
  ui_story_5028_50281301_30_dialog_content = "มันบอกว่าอยากจะปกป้องฉันงั้นเหรอ?",
  ui_story_5028_50281301_31_dialog_content = "โลโล โลโล!",
  ui_story_5028_50281301_32_dialog_content = "ฉันว่ามันเห็นด้วยกับสิ่งที่เธอคิด แล้วมันก็ร้อนรนมาก ๆ!",
  ui_story_5028_50281301_33_dialog_content = "ร้อนรน... แล้วก็เห็นด้วย...",
  ui_story_5028_50281301_34_dialog_content = "เสียงร้องนั่นหมายความว่าอย่างนี้เองเหรอ?",
  ui_story_5028_50281301_35_dialog_content = "รู้แล้ว! ในที่สุดก็รู้จนได้",
  ui_story_5028_50281301_36_dialog_content = "รู้แล้ว? รู้เรื่องอะไรเหรอ?",
  ui_story_5028_50281301_37_dialog_content = "เพราะนายแท้ ๆ ในที่สุดฉันก็แปลเสียงร้องของไคโลได้ซักที",
  ui_story_5028_50281301_38_dialog_content = "ตอนนี้ฉันเข้าใจภาษาของไคโลแล้ว!",
  ui_story_5028_50281301_39_dialog_content = "งั้นเหรอ?",
  ui_story_5028_50281301_40_dialog_content = "โลโลโล! โลโล โล!",
  ui_story_5028_50281301_41_dialog_content = "ม-มันพูดว่าไงเหรอ?",
  ui_story_5028_50281301_42_dialog_content = "มันบอกว่า \"ฉันอยากปกป้องฟีญ่า\"",
  ui_story_5028_50281301_43_dialog_content = "โล!",
  ui_story_5028_50281301_44_dialog_content = "หา? ไคโล แกบอกว่าตัวเองได้รับพลังใหม่จากการสื่อสารกับฟีญ่างั้นเหรอ?",
  ui_story_5028_50281301_45_dialog_content = "งั้นก็ใช้มันเลย!",
  ui_story_5028_50281301_46_dialog_content = "ว้าว ไคโลกำลังเรืองแสง!",
  ui_story_5028_50281301_47_dialog_content = "มันจะแปลงร่างงั้นเหรอ...?!",
  ui_story_5028_50281301_48_dialog_content = "ฟีญ่า ไคโล ใช้พลังใหม่ปราบแกรี่เลย!",
  ui_story_5028_50281301_49_dialog_content = "ไม่ต้องบอกก็ได้นะ เรารู้แล้ว!",
  ui_story_5028_50281301_50_dialog_content = "พลังแค่นั้นคิดว่าจะชนะฉันได้เหรอ? ฝันไปเถอะ",
  ui_story_5028_50281301_51_dialog_content = "ไปซะ เจ้าสัตว์ตัวน้อย กำจัดมัน!",
  ui_story_5028_50281301_52_dialog_content = "กรร!",
  ui_story_5028_50281301_53_dialog_content = "โล!",
  ui_story_5028_50281302_1_dialog_content = "ไปเลย ไคโล สั่งสอนตาลุงชั่วนั่นให้รู้สำนึก ว่าเราจะไม่ยอมให้มันรังแกง่าย ๆ!",
  ui_story_5028_50281302_2_dialog_content = "โล!",
  ui_story_5028_50281302_3_dialog_content = "ป-เป็นไปได้ยังไง?",
  ui_story_5028_50281302_4_dialog_content = "โล! โล โล โล!",
  ui_story_5028_50281302_5_dialog_content = "ไคโลของแกรี่กำลังร้องด้วยความเจ็บปวด",
  ui_story_5028_50281302_6_dialog_content = "ไคโล...",
  ui_story_5028_50281302_7_dialog_content = "ไคโล! เล็งแส้ของแกรี่นะ!",
  ui_story_5028_50281302_8_dialog_content = "โล!!!",
  ui_story_5028_50281302_9_dialog_content = "อัก!",
  ui_story_5028_50281302_10_dialog_content = "จังหวะนี้ล่ะ!",
  ui_story_5028_50281302_11_dialog_content = "ดูให้ดี!",
  ui_story_5028_50281302_12_dialog_content = "ไหม้ไปซะ!",
  ui_story_5028_50281302_13_dialog_content = "คาเรนนีน่า!",
  ui_story_5028_50281302_14_dialog_content = "พวกอิคลิพไซท์โดนกำจัดหมดแล้ว!",
  ui_story_5028_50281302_15_dialog_content = "ฉันจัดการศัตรูตัวสุดท้ายได้ เพราะงั้นนี่เป็นชัยชนะของฉัน",
  ui_story_5028_50281302_16_dialog_content = "เล่นตุกติกน่ะไม่ดีนะ เจเนวีฟ",
  ui_story_5028_50281302_17_dialog_content = "แย่หน่อยนะ ที่จริงตัวสุดท้ายน่ะเป็นฝีมือฉัน",
  ui_story_5028_50281302_18_dialog_content = "เธอน่ะ แค่ทิ้งรอยแส้ไว้ที่ตัวมันเฉย ๆ หลังจากที่มันตายแล้ว",
  ui_story_5028_50281302_19_dialog_content = "เราจัดการพวกมันหมดแล้วเหรอเนี่ย?",
  ui_story_5028_50281302_20_dialog_content = "เราทำได้จริง ๆ ใช่มั้ย...?",
  ui_story_5028_50281302_21_dialog_content = "โล!",
  ui_story_5028_50281302_22_dialog_content = "เยี่ยม!",
  ui_story_5028_50281302_23_dialog_content = "ไอ้พวกทุเรศ...",
  ui_story_5028_50281302_24_dialog_content = "ไคโลทุกตัวเป็นอิสระจากการควบคุมของแกรี่แล้ว!",
  ui_story_5028_50281302_25_dialog_content = "PlayerName ใช้พลังของนายส่งความคิดของฟีญ่าให้กับไคโลตัวอื่นสิ เหมือนที่ทำเมื่อกี้น่ะ!",
  ui_story_5028_50281302_26_dialog_content = "ได้เลย!",
  ui_story_5028_50281302_27_option_content = "บังคับเชื่อมกระแสจิต!",
  ui_story_5028_50281302_28_dialog_content = "แกก็เป็นไคโลเหมือนกันใช่มั้ย?",
  ui_story_5028_50281302_29_dialog_content = "ไม่ต้องกลัวตาแก่ใจร้ายคนนั้นแล้วนะ!",
  ui_story_5028_50281302_30_dialog_content = "เราปลดปล่อยเธอจากการควบคุมของเขาแล้ว เขาไม่มีทางบังคับให้แกทำอะไรที่ไม่อยากทำได้อีกต่อไป!",
  ui_story_5028_50281302_31_dialog_content = "แกไม่ต้องต่อสู้อีกต่อไปแล้ว มาอยู่กับพวกเราเถอะ",
  ui_story_5028_50281302_32_dialog_content = "ฉันเป็นนักสัตว์มหัศจรรย์วิทยา และฉันจะปกป้องแกเอง",
  ui_story_5028_50281302_33_dialog_content = "โล... โล?",
  ui_story_5028_50281302_34_dialog_content = "โล!",
  ui_story_5028_50281302_35_dialog_content = "ไม่ต้องกลัวนะ ฉันไม่เหมือนคนใจร้ายนั่นหรอก ฉันจะดูแลแกเอง",
  ui_story_5028_50281302_36_dialog_content = "...",
  ui_story_5028_50281302_37_dialog_content = "แย่แล้ว ไคโลตัวนี้เคยเจอแต่ความโหดร้ายของแกรี่ ฉันกลัวว่าจิตใจของมันจะรับไม่ไหวแล้วน่ะสิ!",
  ui_story_5028_50281302_38_dialog_content = "เราต้องไปจากที่นี่กันเดี๋ยวนี้ มันต้องใช้เวลาสักพักเพื่อสอนให้เขารู้จักกับวิถีชีวิตอีกแบบนึง",
  ui_story_5028_50281302_39_dialog_content = "ฉันไม่ยอมให้ความฝันที่จะได้รับความยุติธรรม ที่จะได้แก้แค้น ต้องล้มเหลวเพราะคนโง่อย่างพวกแกหรอกนะ!",
  ui_story_5028_50281302_40_dialog_content = "ยอมจำนนต่อฉันซะ เจ้าสัตว์ร้าย!",
  ui_story_5028_50281302_41_dialog_content = "หมดเวลาพักแล้ว!",
  ui_story_5028_50281302_42_dialog_content = "โล... โล...!",
  ui_story_5028_50281302_43_dialog_content = "ไคโลตัวนี้ร้องครวญครางด้วยความเจ็บปวดตลอดเวลา...",
  ui_story_5028_50281302_44_dialog_content = "หยุดนะแกรี่!",
  ui_story_5028_50281302_45_dialog_content = "ยังจะทรมานมันอีกเหรอ?",
  ui_story_5028_50281302_46_dialog_content = "ทรมานเรอะ?",
  ui_story_5028_50281302_47_dialog_content = "แน่นอน!",
  ui_story_5028_50281302_48_dialog_content = "ไม่งั้นมันก็ไม่กลัวฉันน่ะสิ",
  ui_story_5028_50281302_49_dialog_content = "และถ้ามันไม่กลัวฉัน ฉันจะใช้พลังที่แข็งแกร่งที่สุดของมันได้ยังไง?",
  ui_story_5028_50281302_50_dialog_content = "ทีนี้ก็ใช้พลังทั้งหมดของแกทำลายพวกมันซะ!",
  ui_story_5028_50281302_51_dialog_content = "ไม่งั้นแกจะได้พบกับความเจ็บปวดที่แท้จริงด้วยมือของฉัน!",
  ui_story_5028_50281302_52_dialog_content = "โล, โล! โล!",
  ui_story_5028_50281302_53_dialog_content = "โล!",
  ui_story_5028_50281302_54_dialog_content = "อ๊ะ ไม่นะ? ทำไงดีล่ะ? มันร้องขอความช่วยเหลือใหญ่แล้ว!",
  ui_story_5028_50281302_55_dialog_content = "เราควรปราบมันอีกทีไหม?",
  ui_story_5028_50281302_56_dialog_content = "โล!",
  ui_story_5028_50281302_57_dialog_content = "หยุดนะฟีญ่า!",
  ui_story_5028_50281302_58_dialog_content = "ไคโลตัวนี้อ่อนแอมากแล้ว ถ้าโดนโจมตีอีกทีมันไม่รอดแน่",
  ui_story_5028_50281302_59_dialog_content = "งั้นเอาไงดีล่ะอาจารย์?",
  ui_story_5028_50281302_60_dialog_content = "สำหรับไคโลที่บอบช้ำขนาดนั้น ฉันว่าขึ้นอยู่กับโชคชะตาแล้วแหละ",
  ui_story_5028_50281302_61_dialog_content = "ฉันจะไม่เชื่อนายเด็ดขาด ฉันเรียนรู้ที่จะไม่เชื่อนายแล้ว!",
  ui_story_5028_50281302_62_dialog_content = "ฮ่าฮ่า! งั้นก็ขอให้โชคดีนะ เพราะนั่นคือความหวังสุดท้ายของพวกแกแล้ว",
  ui_story_5028_50281302_63_dialog_content = "ทีนี้ก็ได้เวลาสำหรับ—",
  ui_story_5028_50281302_64_dialog_content = "ฉันเบื่อการต่อสู้ที่สุด มันคือส่วนที่แย่ที่สุดของเรื่องนี้เลย",
  ui_story_5028_50281302_65_dialog_content = "แกมาจากไหนน่ะ?!",
  ui_story_5028_50281302_66_dialog_content = "แต่ไม่ว่าอะไรก็ตาม ยังไงมันก็ดีกว่าปล่อยให้คนอย่างแกเป็นอิสระทั้งนั้น!",
  ui_story_5028_50281302_67_dialog_content = "กรร!!!",
  ui_story_5028_50281302_68_dialog_content = "เฮ้ย! ทำไมแกถึง...",
  ui_story_5028_50281302_69_option_content = "โชคดีชะมัด... มันกลายร่างเป็นชีร่า!",
  ui_story_5028_50281302_70_option_content = "ชีร่าทุบพื้นอย่างแรงแล้วเตะแกรี่ลอยกระเด็นขึ้นฟ้า!",
  ui_story_5028_50281302_71_dialog_content = "นี่ไม่เกี่ยวอะไรกับโชคชะตาเลยสักนิด",
  ui_story_5028_50281302_72_dialog_content = "ก็แค่การเปลี่ยนแปลงเชิงคุณภาพ ซึ่งมีผลมาจากความพยายามทั้งหมดของฉันจนถึงตอนนี้เท่านั้นเอง",
  ui_story_5028_50281302_73_dialog_content = "ชีร่า!",
  ui_story_5028_50281302_74_dialog_content = "โชคดีนะที่ฉันมองการณ์ไกล บอกให้เดรโก้ไลออนมาช่วยชีร่าปกป้องคนอื่นได้",
