  ui_story_5028_50281302_76_dialog_content = "อุตส่าห์จะชมอยู่แล้วเชียวว่าเธอเป็นผู้ใหญ่ขึ้นมาก...",
  ui_story_5028_50281302_77_dialog_content = "โล...",
  ui_story_5028_50281302_78_dialog_content = "หือ?",
  ui_story_5028_50281302_79_dialog_content = "โล โล?!",
  ui_story_5028_50281302_80_dialog_content = "ไม่อยากนึกเลย ว่าเจ้านี่ต้องทนทุกข์กับอะไรบ้างตอนที่อยู่กับแกรี่",
  ui_story_5028_50281302_81_dialog_content = "ให้มันพักสักหน่อยดีไหม?",
  ui_story_5028_50281302_82_dialog_content = "แล้วเราจะทำยังไงกับคุณศัตรูหมายเลขหนึ่งของสังคมดีล่ะ?",
  ui_story_5028_50281302_83_dialog_content = "ค่อก ... อัก!",
  ui_story_5028_50281302_84_dialog_content = "(ชีร่ายกร่างของแกรี่ขึ้นมาโดยใช้หนวดเส้นหนึ่งแล้วนำตัวเขามา)",
