  ui_story_5028_50281302_86_dialog_content = "(เธอน่ากลัวมากเลย!)",
  ui_story_5028_50281302_87_dialog_content = "โล โล โล...",
  ui_story_5028_50281302_88_dialog_content = "อึก... ดูเหมือนว่า... ฉันจะ... แพ้แล้วสินะ...",
  ui_story_5028_50281302_89_dialog_content = "ฆ่าฉันซะสิ",
  ui_story_5028_50281302_90_dialog_content = "มันอาจเป็นชะตาของฉันก็ได้ที่ต้องตายด้วยน้ำมือของสัตว์เดรัจฉานพวกนี้",
