  ui_story_5028_50281302_92_dialog_content = "ฉันว่าเพื่อประโยชน์สูงสุด เราต้อง...",
  ui_story_5028_50281302_93_dialog_content = "ฉันว่าเราควรฟังความเห็นจากแม่งานคนสำคัญที่ช่วยให้เราประสบความสำเร็จในวันนี้ดีกว่านะ เอาล่ะ ฟีญ่า เธอว่าเราควรทำยังไงกับเขาดี?",
  ui_story_5028_50281302_94_dialog_content = "...",
  ui_story_5028_50281302_95_dialog_content = "ฟีญ่า?",
  ui_story_5028_50281302_96_dialog_content = "แน่นอน เราควรปล่อยให้คนชั่วแบบนี้เน่าตายอยู่ในคุกเพราะความผิดที่ก่อไว้!",
