  ui_story_5028_50281302_98_dialog_content = "หา? เน่าตายในคุกเหรอ?",
  ui_story_5028_50281302_99_dialog_content = "ถึงจะอยู่ในคุก แต่ฉันก็ไม่ล้มเลิกแผนการแก้แค้นง่าย ๆ หรอกนะ",
  ui_story_5028_50281302_100_dialog_content = "ถ้าอย่างนั้น นักสัตว์มหัศจรรย์วิทยาฟีญ่า ก็จะหยุดยั้งแกอีกครั้ง!",
  ui_story_5028_50281302_101_dialog_content = "แกจะได้เห็นว่าสัตว์มหัศจรรย์ของฉันทรงพลังมากขึ้นได้แค่ไหน ภายใต้การปกป้องดูแลของฉันในช่วงเวลานั้น—",
