  ui_story_5028_50281302_103_dialog_content = "เยี่ยมมาก กล่าวได้น่าประทับใจเหลือเกิน",
  ui_story_5028_50281302_104_dialog_content = "คุณพระ! นายดูเหมือนชีร่าเป๊ะเลย ว่าแต่ นายเป็นมนุษย์ปลาหมึกยักษ์เหรอ?",
