  ui_story_5028_50281401_11_dialog_content = "ทำไมอาจารย์วิคถึงไม่ประสบความสำเร็จอะไรซักอย่าง ทั้ง ๆ ที่มีสัตว์มหัศจรรย์สุดแกร่งอยู่ที่ปลายนิ้ว?",
