  ui_story_5028_50281401_124_dialog_content = "อย่าลืมดูแลเธอด้วยนะ เรื่องแบบนี้อาจเป็นเรื่องที่ยากลำบากและน่าหงุดหงิดได้",
  ui_story_5028_50281401_125_dialog_content = "ฉันไม่ได้มีประสบการณ์อะไรมากนักกับเด็ก ๆ รบกวนให้ลูกศิษย์ผู้ทรงเกียรติดูแลแทนได้ไหมเนี่ย?",
  ui_story_5028_50281401_126_dialog_content = "เอ่อ...",
